CREATE OR REPLACE FUNCTION finance_private.close_cash_period(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;account uuid;actor uuid:=auth.uid();actor_name text;starts date;ends date;count_id uuid;snapshot jsonb;prior public.finance_commands%rowtype;c public.finance_account_period_closures%rowtype;previous_id uuid;dep jsonb;result jsonb;
begin
 if jsonb_typeof(_payload) is distinct from 'object' or _payload->'version' is distinct from '1'::jsonb or jsonb_typeof(_payload->'reason') is distinct from 'string' or length(btrim(_payload->>'reason')) not between 10 and 2000 or coalesce(_payload->>'revision','') !~ '^[0-9a-f]{32}$' or coalesce(_payload->>'from','') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(_payload->>'to','') !~ '^\d{4}-\d{2}-\d{2}$' or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','account_id','from','to','count_id','revision','reason')) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;account:=(_payload->>'account_id')::uuid;starts:=(_payload->>'from')::date;ends:=(_payload->>'to')::date;count_id:=(_payload->>'count_id')::uuid;
 if t is null or request is null or account is null or count_id is null then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;if found then if prior.actor_id<>actor or prior.action<>'close_cash_period' or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;return prior.result;end if;
 perform 1 from public.bank_accounts where tenant_id=t order by id for update;
 perform 1 from public.finance_cash_period_counts where tenant_id=t and id=count_id for update;
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 snapshot:=finance_private.cash_period_close_snapshot(t,account,starts,ends,count_id);
 if snapshot->>'revision' is distinct from _payload->>'revision' then raise exception 'finance_period_close_changed' using errcode='40001';end if;
 if snapshot->'eligible' is distinct from 'true'::jsonb or not finance_private.cash_period_guards_ready() then raise exception 'finance_period_close_blocked' using errcode='23514';end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;actor_name:=coalesce(actor_name,actor::text);
 select id into previous_id from public.finance_account_period_closures where tenant_id=t and account_id=account and period_start=starts and period_end=ends order by created_at desc,id desc limit 1;
 insert into finance_private.account_close_write_tickets values(txid_current(),t,request,actor,'finance_account_period_closures');
 insert into public.finance_account_period_closures(tenant_id,account_id,period_start,period_end,opening_id,predecessor_id,previous_closure_id,snapshot,snapshot_revision,actor_id,actor_name,reason,request_id) values(t,account,starts,ends,(snapshot->>'opening_id')::uuid,(snapshot->>'predecessor_id')::uuid,previous_id,snapshot,snapshot->>'revision',actor,actor_name,btrim(_payload->>'reason'),request) returning * into c;
 for dep in select value from jsonb_array_elements(snapshot->'dependencies') loop
 insert into public.finance_account_period_dependencies values(t,c.id,dep->>'source_kind',(dep->>'source_id')::uuid,dep->>'source_revision',(dep->>'account_id')::uuid,(dep->>'affected_from')::date,(dep->>'affected_to')::date,dep->>'dependency_role');end loop;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'account_id',account,'closure_id',c.id,'from',starts,'to',ends,'revision',c.snapshot_revision,'confirmed',true,'cash_changed',false);
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data) values(t,'account_period',c.id,'cash_period_closed',actor,actor_name,btrim(_payload->>'reason'),snapshot,result);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'close_cash_period',_payload,result);return result;
end$function$

CREATE OR REPLACE FUNCTION finance_private.guard_closed_financial_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare data jsonb;t uuid;identity jsonb;bank public.bank_accounts%rowtype;begin
 if tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return new;end if;
 for data in select value from jsonb_array_elements(case when tg_op='INSERT' then jsonb_build_array(to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(old),to_jsonb(new)) end) loop
  t:=(data->>'tenant_id')::uuid;
  if t is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
  if not pg_try_advisory_xact_lock(hashtextextended(t::text||':finance',0)) then raise exception 'finance_period_source_busy' using errcode='40001';end if;
  if not finance_private.closed_interval_exists(t,null,null,null) then continue;end if;
 if tg_op='INSERT' then
  if tg_table_name='employee_advances' then if new.status='paid' then continue;end if;
  elsif tg_table_name='payroll_entry_items' then if new.nature='already_paid' then continue;end if;end if;
 end if;
 if tg_op='UPDATE' and tg_table_name='employee_advances' then
  if old.status is distinct from 'paid' and new.status='paid' and to_jsonb(old)-array['status','paid_by','paid_at','updated_by','updated_at'] is not distinct from to_jsonb(new)-array['status','paid_by','paid_at','updated_by','updated_at'] then continue;end if;
 end if;
  if tg_op='INSERT' and tg_table_name in('payables_payments','receivables_payments','driver_settlement_payments','bank_transactions','load_payments','closing_report_payments') then continue;end if;
  if tg_table_name='bank_accounts' then
   if tg_op='UPDATE' and (to_jsonb(old)-array['name','bank_name','pix_key','updated_at'])=(to_jsonb(new)-array['name','bank_name','pix_key','updated_at']) then continue;end if;
   if exists(select 1 from public.finance_account_period_closures c where c.tenant_id=t and c.account_id=(data->>'id')::uuid and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   if exists(select 1 from public.bank_accounts b join public.finance_account_period_closures c on c.tenant_id=b.tenant_id and c.account_id=b.id where b.tenant_id=t and b.id<>(data->>'id')::uuid and regexp_replace(coalesce(b.bank_code,''),'\D','','g')=regexp_replace(coalesce(data->>'bank_code',''),'\D','','g') and regexp_replace(coalesce(b.branch_number,''),'\D','','g')=regexp_replace(coalesce(data->>'branch_number',''),'\D','','g') and regexp_replace(coalesce(b.account_number,''),'\D','','g')=regexp_replace(coalesce(data->>'account_number',''),'\D','','g') and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_closed_account_identity_conflict' using errcode='55000';end if;
  elsif tg_table_name='payroll_entry_items' and data->>'nature' is distinct from 'already_paid' then continue;
  else perform finance_private.assert_closed_source_mutable(t,tg_table_name,data);end if;
 end loop;
 if tg_op='DELETE' then return old;end if;return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.guard_late_paid_projection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row jsonb;chain jsonb;f jsonb;actor_name text;proven boolean:=true;begin
 if not pg_try_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0)) then raise exception 'finance_period_source_busy' using errcode='40001';end if;
 if not finance_private.closed_interval_exists(new.tenant_id,null,null,null) then return new;end if;
 execute format('select to_jsonb(x) from public.%I x where tenant_id=$1 and id=$2',tg_table_name) into current_row using new.tenant_id,new.id;
 if current_row is null then return new;end if;
 if tg_table_name='employee_advances' and current_row->>'status' is distinct from 'paid' then perform finance_private.assert_closed_source_mutable(new.tenant_id,tg_table_name,current_row);return new;end if;
 if tg_table_name='payroll_entry_items' and current_row->>'nature' is distinct from 'already_paid' then return new;end if;
 chain:=finance_private.paid_projection_chain(new.tenant_id,tg_table_name,new.id);
 if chain->'valid' is distinct from 'true'::jsonb or jsonb_array_length(chain->'footprints')=0 then proven:=false;
 else for f in select value from jsonb_array_elements(chain->'footprints') loop
  if finance_private.closed_interval_exists(new.tenant_id,(f->>'account_id')::uuid,(f->>'occurred_on')::date,(f->>'occurred_on')::date) and not finance_private.frozen_movement(new.tenant_id,(f->>'movement_id')::uuid) then proven:=false;end if;
 end loop;end if;
 if proven then
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text) into actor_name from auth.users where id=auth.uid();
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data) values(new.tenant_id,'late_period_composition',new.id,'closed_period_composition_recorded',auth.uid(),coalesce(actor_name,auth.uid()::text),'Projeção de pagamentos canônicos conferida por cadeia de IDs',chain||jsonb_build_object('cash_changed',false));return new;
 end if;
 perform finance_private.assert_closed_source_mutable(new.tenant_id,tg_table_name,current_row);return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.guard_late_payment_composition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row jsonb;actor_name text;begin
 if not pg_try_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0)) then raise exception 'finance_period_source_busy' using errcode='40001';end if;
 execute format('select to_jsonb(p) from public.%I p where p.tenant_id=$1 and p.id=$2',tg_table_name) into current_row using new.tenant_id,new.id;
 if current_row is null then return new;end if;
 if finance_private.closed_interval_exists(new.tenant_id,null,null,null) and finance_private.late_payment_composition_proved(new.tenant_id,tg_table_name,current_row) then
  if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
  select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text) into actor_name from auth.users where id=auth.uid();
  insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data) values(new.tenant_id,'late_period_composition',new.id,'closed_period_composition_recorded',auth.uid(),coalesce(actor_name,auth.uid()::text),'Detalhamento posterior vinculado a dinheiro já congelado',jsonb_build_object('source_table',tg_table_name,'source_id',new.id,'cash_changed',false,'source',current_row));
  return new;
 end if;
 perform finance_private.assert_closed_source_mutable(new.tenant_id,tg_table_name,current_row);return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.legacy_cut_review_status(_tenant uuid, _account uuid, _from date, _to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare manifest jsonb;review public.finance_legacy_cut_reviews%rowtype;current boolean;approved boolean;
begin
 manifest:=finance_private.legacy_cut_manifest(_tenant,_account,_from,_to);
 select * into review from public.finance_legacy_cut_reviews where tenant_id=_tenant and bank_account_id=_account and period_start=_from and period_end=_to order by created_at desc,id desc limit 1;
 current:=review.id is not null and review.revision=manifest->>'revision';approved:=current and jsonb_array_length(manifest->'blockers')=0;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'account_id',_account,'from',_from,'to',_to,'revision',manifest->>'revision','current',current,'approved',approved,'can_review',finance_private.can_review_legacy_cut(_tenant),'status',case when approved then 'approved' when review.id is not null then 'needs_review' else 'not_approved' end,'review_id',review.id,'approval',case when review.id is not null then to_jsonb(review)-'snapshot' end,'blockers',manifest->'blockers','manifest',manifest,'history',coalesce((select jsonb_agg(to_jsonb(h)-'snapshot' order by created_at desc,id desc) from public.finance_legacy_cut_reviews h where h.tenant_id=_tenant and h.bank_account_id=_account and h.period_start=_from and h.period_end=_to),'[]'));
end$function$

CREATE OR REPLACE FUNCTION finance_private.manage_account_period_close(_payload jsonb, _reopen boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;actor uuid:=auth.uid();account uuid;start_date date;end_date date;action text;reason text;actor_name text;prior public.finance_commands%rowtype;c public.finance_account_period_closures%rowtype;snapshot jsonb;result jsonb;newid uuid;previous_id uuid;dep jsonb;
begin
 if jsonb_typeof(_payload) is distinct from 'object' or _payload->'version' is distinct from '1'::jsonb or jsonb_typeof(_payload->'reason') is distinct from 'string' or length(btrim(_payload->>'reason')) not between 10 and 2000 or coalesce(_payload->>'revision','') !~ '^[0-9a-f]{32,64}$'
 or exists(select 1 from jsonb_object_keys(_payload) k where k<>all(case when _reopen then array['version','tenant_id','request_id','closure_id','revision','reason'] else array['version','tenant_id','request_id','account_id','from','to','revision','reason'] end)) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;reason:=btrim(_payload->>'reason');
 if t is null or request is null then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if not _reopen and (jsonb_typeof(_payload->'from') is distinct from 'string' or jsonb_typeof(_payload->'to') is distinct from 'string' or coalesce(_payload->>'from','') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(_payload->>'to','') !~ '^\d{4}-\d{2}-\d{2}$') then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 action:=case when _reopen then 'reopen_account_period' else 'close_account_period' end;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;
 if found then if prior.actor_id<>actor or prior.action<>action or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;return prior.result;end if;
 if _reopen then
  select * into c from public.finance_account_period_closures where tenant_id=t and id=(_payload->>'closure_id')::uuid;
  if not found then raise exception 'finance_period_closure_not_found' using errcode='22023';end if;account:=c.account_id;
 else account:=(_payload->>'account_id')::uuid;start_date:=(_payload->>'from')::date;end_date:=(_payload->>'to')::date;end if;
 if account is null then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 perform 1 from public.bank_accounts where tenant_id=t order by id for update;
 if not finance_private.can_close_account_period(t) then raise exception 'finance_close_access_denied' using errcode='42501';end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;actor_name:=coalesce(actor_name,actor::text);
 if _reopen then
  if c.snapshot_revision is distinct from _payload->>'revision' then raise exception 'finance_period_close_changed' using errcode='40001';end if;
  if exists(select 1 from public.finance_account_period_reopenings where tenant_id=t and closure_id=c.id) then raise exception 'finance_period_already_reopened' using errcode='23514';end if;
  insert into finance_private.account_close_write_tickets values(txid_current(),t,request,actor,'finance_account_period_reopenings');
  insert into public.finance_account_period_reopenings(tenant_id,closure_id,expected_snapshot_revision,actor_id,actor_name,reason,request_id) values(t,c.id,c.snapshot_revision,actor,actor_name,reason,request) returning id into newid;
  result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'account_id',account,'closure_id',c.id,'reopening_id',newid,'confirmed',true,'cash_changed',false);
 else
  if start_date is null or end_date is null or not isfinite(start_date) or not isfinite(end_date) or end_date<start_date or end_date-start_date>=366 then raise exception 'finance_invalid_filters' using errcode='22023';end if;
  snapshot:=finance_private.account_period_close_snapshot(t,account,start_date,end_date);
  if snapshot->>'revision' is distinct from _payload->>'revision' then raise exception 'finance_period_close_changed' using errcode='40001';end if;
  if snapshot->'eligible' is distinct from 'true'::jsonb or not finance_private.account_period_guards_ready() then raise exception 'finance_period_close_blocked' using errcode='23514';end if;
  if jsonb_typeof(snapshot->'dependencies') is distinct from 'array' or not exists(select 1 from jsonb_array_elements(snapshot->'dependencies') d where d->>'source_kind'='finance_account_openings' and d->>'source_id'=snapshot->>'opening_id') then raise exception 'finance_period_dependencies_incomplete' using errcode='23514';end if;
  select old.id into previous_id from public.finance_account_period_closures old where old.tenant_id=t and old.account_id=account and old.period_start=start_date and old.period_end=end_date order by old.created_at desc,old.id desc limit 1;
  insert into finance_private.account_close_write_tickets values(txid_current(),t,request,actor,'finance_account_period_closures');
  insert into public.finance_account_period_closures(tenant_id,account_id,period_start,period_end,opening_id,predecessor_id,previous_closure_id,snapshot,snapshot_revision,actor_id,actor_name,reason,request_id)
  values(t,account,start_date,end_date,(snapshot->>'opening_id')::uuid,(snapshot->>'predecessor_id')::uuid,previous_id,snapshot,snapshot->>'revision',actor,actor_name,reason,request) returning * into c;
  for dep in select value from jsonb_array_elements(snapshot->'dependencies') loop
   insert into public.finance_account_period_dependencies values(t,c.id,dep->>'source_kind',(dep->>'source_id')::uuid,dep->>'source_revision',(dep->>'account_id')::uuid,(dep->>'affected_from')::date,(dep->>'affected_to')::date,dep->>'dependency_role');
  end loop;
  result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'account_id',account,'closure_id',c.id,'from',start_date,'to',end_date,'revision',c.snapshot_revision,'confirmed',true,'cash_changed',false);
 end if;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data) values(t,'account_period',c.id,case when _reopen then 'account_period_reopened' else 'account_period_closed' end,actor,actor_name,reason,c.snapshot,result);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,action,_payload,result);return result;
end$function$

CREATE OR REPLACE FUNCTION finance_private.reconcile_bank_group(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;actor uuid:=auth.uid();actor_name text;existing public.finance_commands%rowtype;
 movements uuid[];entries uuid[];snapshot jsonb;item jsonb;account uuid;direction text;movement_total numeric;entry_total numeric;
 group_id uuid:=gen_random_uuid();result jsonb;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _payload->>'version' is distinct from '1' or jsonb_typeof(_payload->'movement_ids') is distinct from 'array'
  or jsonb_typeof(_payload->'bank_entry_ids') is distinct from 'array' or length(btrim(coalesce(_payload->>'reason',''))) not between 10 and 2000
  or length(btrim(coalesce(_payload->>'account_evidence',''))) not between 10 and 2000
  or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','movement_ids','bank_entry_ids','expected_revision','reason','account_evidence')) then
  raise exception 'finance_invalid_reconciliation' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'reconcile_bank_group' or existing.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;
  return existing.result;
 end if;
 select array_agg(value::uuid) into movements from jsonb_array_elements_text(_payload->'movement_ids');
 select array_agg(value::uuid) into entries from jsonb_array_elements_text(_payload->'bank_entry_ids');
 snapshot:=finance_private.reconciliation_context(t,movements,entries);
 if snapshot->>'revision' is distinct from _payload->>'expected_revision' then raise exception 'finance_reconciliation_context_changed' using errcode='40001';end if;
 if exists(select 1 from jsonb_array_elements(snapshot->'history') h where h->>'reversal_id' is null) then
  raise exception 'finance_reconciliation_already_linked' using errcode='23514';end if;
 account:=(snapshot#>>'{movements,0,bank_account_id}')::uuid;direction:=snapshot#>>'{movements,0,direction}';
 perform 1 from public.bank_accounts a where a.tenant_id=t and a.id=account and to_jsonb(a)->>'account_type' is distinct from 'cash' for share;
 if not found then raise exception 'finance_reconciliation_bank_account_required' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(snapshot->'movements') loop
  if (item->>'bank_account_id')::uuid<>account or item->>'direction'<>direction then raise exception 'finance_reconciliation_account_or_direction_mismatch' using errcode='22023';end if;
 end loop;
 for item in select value from jsonb_array_elements(snapshot->'entries') loop
  if (item->>'bank_account_id')::uuid<>account or ((item->>'amount_cents')::bigint>0)<>(direction='in') then
   raise exception 'finance_reconciliation_account_or_direction_mismatch' using errcode='22023';end if;
  if item->>'active' is distinct from 'true' or item#>>'{source_verification,outcome}' is distinct from 'rows_match' then
   raise exception 'finance_reconciliation_source_not_verified' using errcode='22023';end if;
 end loop;
 select sum((m->>'amount_cents')::numeric) into movement_total from jsonb_array_elements(snapshot->'movements') m;
 select sum(abs((e->>'amount_cents')::numeric)) into entry_total from jsonb_array_elements(snapshot->'entries') e;
 if movement_total<>entry_total or movement_total not between 1 and 99999999999999 then raise exception 'finance_reconciliation_amount_mismatch' using errcode='22023';end if;
 select coalesce(raw_user_meta_data->>'full_name',email,actor::text) into actor_name from auth.users where id=actor;
 insert into public.finance_reconciliation_groups(id,tenant_id,bank_account_id,direction,amount_cents,movement_ids,bank_entry_ids,method,actor_id,actor_name,reason,account_evidence,evidence_snapshot)
 values(group_id,t,account,direction,movement_total,movements,entries,'manual',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),btrim(_payload->>'account_evidence'),snapshot);
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'group_id',group_id,'amount_cents',movement_total::text,'manual',true,'confirmed',true);
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(t,'reconciliation_group',group_id,'bank_reconciled_manually',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),result);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'reconcile_bank_group',_payload,result);
 return result;
end;$function$

CREATE OR REPLACE FUNCTION finance_private.run_automatic_reconciliation_queue()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare job record;matched integer:=0;error_code text;begin
 if not pg_try_advisory_xact_lock(hashtextextended('finance:auto-reconciliation-worker',0)) then return 0;end if;
 for job in select verification_id,tenant_id,import_id,actor_id from public.finance_automatic_reconciliation_jobs where status='pending' order by updated_at,verification_id limit 10 loop
  begin matched:=matched+finance_private.process_automatic_reconciliation(job.verification_id);
  exception when others then
   get stacked diagnostics error_code=returned_sqlstate;
   update public.finance_automatic_reconciliation_jobs set status='review',issue='processing_error:'||error_code,updated_at=clock_timestamp() where verification_id=job.verification_id;
  end;
 end loop;return matched;
end;$function$

CREATE OR REPLACE FUNCTION public.review_finance_legacy_cut(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;account uuid;request uuid;starts date;ends date;manifest jsonb;prior public.finance_commands%rowtype;actor uuid:=auth.uid();actor_name text;review_id uuid;result jsonb;
begin
 t:=(_payload->>'tenant_id')::uuid;account:=(_payload->>'account_id')::uuid;request:=(_payload->>'request_id')::uuid;starts:=(_payload->>'from')::date;ends:=(_payload->>'to')::date;
 if not finance_private.can_review_legacy_cut(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if jsonb_typeof(_payload) is distinct from 'object' or _payload->'version' is distinct from '1'::jsonb or request is null or account is null or coalesce(_payload->>'revision','') !~ '^[a-f0-9]{32}$' or length(btrim(coalesce(_payload->>'reason',''))) not between 10 and 2000 or _payload->'sources_reviewed' is distinct from 'true'::jsonb or exists(select 1 from jsonb_object_keys(_payload) k where k<>all(array['version','tenant_id','request_id','account_id','from','to','revision','reason','sources_reviewed'])) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 perform 1 from public.bank_accounts where tenant_id=t and id=account for share;
 if not finance_private.can_review_legacy_cut(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;
 if found then if prior.actor_id<>actor or prior.payload<>_payload or prior.action<>'review_legacy_cut' then raise exception 'finance_request_conflict' using errcode='23505';end if;return prior.result;end if;
 manifest:=finance_private.legacy_cut_manifest(t,account,starts,ends);
 if manifest->>'revision'<>_payload->>'revision' then raise exception 'finance_legacy_cut_changed' using errcode='40001';end if;
 if jsonb_array_length(manifest->'blockers')>0 then raise exception 'finance_legacy_cut_unresolved' using errcode='23514';end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;actor_name:=coalesce(actor_name,actor::text);
 insert into public.finance_legacy_cut_reviews(tenant_id,bank_account_id,period_start,period_end,revision,snapshot,actor_id,actor_name,reason) values(t,account,starts,ends,manifest->>'revision',manifest,actor,actor_name,btrim(_payload->>'reason')) returning id into review_id;
 result:=jsonb_build_object('version',1,'tenant_id',t,'account_id',account,'from',starts,'to',ends,'request_id',request,'review_id',review_id,'revision',manifest->>'revision','confirmed',true,'cash_changed',false);
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data) values(t,'legacy_cut',review_id,'legacy_cut_reviewed',actor,actor_name,btrim(_payload->>'reason'),result);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'review_legacy_cut',_payload,result);return result;
end$function$

