CREATE OR REPLACE FUNCTION finance_private.account_opening(_tenant uuid, _account uuid, _from date, _to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.finance_account_openings%rowtype;active jsonb;book jsonb;history jsonb;evidence jsonb;valid boolean;prior_net numeric;incoming numeric;outgoing numeric;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _from is null or _to is null or _from>_to or _to-_from>3660 then raise exception 'finance_invalid_period' using errcode='22023';end if;
 if not exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=_account) then raise exception 'finance_account_not_found' using errcode='22023';end if;
 select * into o from public.finance_account_openings a where a.tenant_id=_tenant and a.bank_account_id=_account
  and not exists(select 1 from public.finance_account_opening_reversals r where r.tenant_id=_tenant and r.opening_id=a.id);
 if found then
  if o.evidence_type='cash_count_v1' then
   valid:=finance_private.cash_opening_evidence_valid(o.evidence,o.effective_from,o.balance_cents)
    and exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=_account and account_type='cash');
  else
  evidence:=finance_private.statement_period_evidence(_tenant,_account,o.effective_from,o.evidence_to);
  valid:=evidence->>'opening_balance_cents'=o.balance_cents::text and not exists(select 1 from jsonb_array_elements(o.evidence->'opening_anchors') saved
   where not exists(select 1 from jsonb_array_elements(evidence->'anchors') current_anchor where current_anchor=saved));
  end if; active:=jsonb_build_object('evidence_type',o.evidence_type,'evidence',case when o.evidence_type='cash_count_v1' then o.evidence else jsonb_build_object('opening_anchors',o.evidence->'opening_anchors') end,'id',o.id,'effective_from',o.effective_from,'balance_cents',o.balance_cents::text,'actor_id',o.actor_id,'actor_name',o.actor_name,'reason',o.reason,'created_at',o.created_at,'evidence_status',case when coalesce(valid,false) then 'valid' else 'requires_review' end);
  if _from>=o.effective_from then
   select coalesce(sum(case when direction='in' then amount_cents else -amount_cents end),0) into prior_net from public.finance_movements
    where tenant_id=_tenant and bank_account_id=_account and occurred_on>=o.effective_from and occurred_on<_from;
   select coalesce(sum(amount_cents) filter(where direction='in'),0),coalesce(sum(amount_cents) filter(where direction='out'),0) into incoming,outgoing
    from public.finance_movements where tenant_id=_tenant and bank_account_id=_account and occurred_on between _from and _to;
   book:=jsonb_build_object('opening_cents',(o.balance_cents+prior_net)::text,'in_cents',incoming::text,'out_cents',outgoing::text,'closing_cents',(o.balance_cents+prior_net+incoming-outgoing)::text);
  end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('evidence_type',a.evidence_type,'evidence',case when a.evidence_type='cash_count_v1' then a.evidence else jsonb_build_object('opening_anchors',a.evidence->'opening_anchors') end,'id',a.id,'effective_from',a.effective_from,'balance_cents',a.balance_cents::text,'actor_id',a.actor_id,'actor_name',a.actor_name,'reason',a.reason,'created_at',a.created_at,
  'reversal',case when r.id is null then null else jsonb_build_object('id',r.id,'actor_id',r.actor_id,'actor_name',r.actor_name,'reason',r.reason,'created_at',r.created_at) end) order by a.created_at,a.id),'[]') into history
  from public.finance_account_openings a left join public.finance_account_opening_reversals r on r.tenant_id=_tenant and r.opening_id=a.id where a.tenant_id=_tenant and a.bank_account_id=_account;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'account_id',_account,'from',_from,'to',_to,'opening',active,'book',book,'history',history,'can_close',false);
end$function$

CREATE OR REPLACE FUNCTION finance_private.account_period_close_snapshot(_tenant uuid, _account uuid, _from date, _to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account public.bank_accounts%rowtype;o public.finance_account_openings%rowtype;predecessor public.finance_account_period_closures%rowtype;
 coverage jsonb;opening jsonb;review jsonb;legacy jsonb;facts jsonb;result jsonb;dependencies jsonb;reasons text[]:='{}';k text;
 initial numeric;closing numeric;guards boolean:=false;overlap boolean;opening_evidence jsonb;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _from is null or _to is null or not isfinite(_from) or not isfinite(_to) or _from>_to or _to-_from>=366 then raise exception 'finance_invalid_period' using errcode='22023';end if;
 select * into account from public.bank_accounts where tenant_id=_tenant and id=_account;
 if not found then raise exception 'finance_account_not_found' using errcode='22023';end if;
 if account.active is distinct from true or account.account_type not in('checking','savings') then reasons:=array_append(reasons,'bank_account_required');end if;
 if _to>=(statement_timestamp() at time zone 'America/Sao_Paulo')::date then reasons:=array_append(reasons,'period_not_finished');end if;
 review:=finance_private.account_period_review(_tenant,_account,_from,_to);
 coverage:=finance_private.statement_coverage_review(_tenant,_account,_from,_to);
 opening:=finance_private.account_opening(_tenant,_account,_from,_to);
 select * into o from public.finance_account_openings a where tenant_id=_tenant and bank_account_id=_account
  and not exists(select 1 from public.finance_account_opening_reversals r where r.tenant_id=a.tenant_id and r.opening_id=a.id);
 select * into predecessor from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=_account and c.period_end<_from
  and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id) order by c.period_end desc,c.id limit 1;
 select exists(select 1 from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=_account and c.period_start<=_to and c.period_end>=_from
  and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) into overlap;
 if overlap then reasons:=array_append(reasons,'period_already_closed');end if;
 if o.id is null or opening#>>'{opening,evidence_status}' is distinct from 'valid' then reasons:=array_append(reasons,'opening_requires_review');end if;
 if predecessor.id is null then
  if o.effective_from is distinct from _from then reasons:=array_append(reasons,'period_must_start_at_opening');end if;initial:=o.balance_cents;
 else
  if predecessor.period_end+1<>_from or predecessor.opening_id is distinct from o.id then reasons:=array_append(reasons,'predecessor_not_contiguous');end if;
  initial:=nullif(predecessor.snapshot#>>'{balances,closing_cents}','')::numeric;
 end if;
 if coverage->>'status' is distinct from 'approved' or coverage->'current' is distinct from 'true'::jsonb then reasons:=array_append(reasons,'coverage_requires_review');end if;
 closing:=nullif(coverage#>>'{evidence,closing_balance_cents}','')::numeric;
 if initial is null or closing is null or initial is distinct from nullif(coverage#>>'{evidence,opening_balance_cents}','')::numeric
  or initial+(review#>>'{recorded,net_cents}')::numeric is distinct from closing then reasons:=array_append(reasons,'balance_mismatch');end if;
 if review#>>'{difference,in_cents}' is distinct from '0' or review#>>'{difference,out_cents}' is distinct from '0' or review#>>'{difference,net_cents}' is distinct from '0' then reasons:=array_append(reasons,'bank_ledger_difference');end if;
 foreach k in array array['unmatched_bank_count','unmatched_movement_count','evidence_review_count','cross_period_count','unverified_entry_count','unresolved_row_count'] loop
  if coalesce((review->>k)::bigint,-1)<>0 then reasons:=array_append(reasons,k);end if;
 end loop;
 if to_regprocedure('finance_private.legacy_cut_review_status(uuid,uuid,date,date)') is null then
  legacy:=jsonb_build_object('current',false,'approved',false,'status','not_approved','blockers',jsonb_build_array('classifier_missing'));reasons:=array_append(reasons,'legacy_classifier_missing');
 else
  execute 'select finance_private.legacy_cut_review_status($1,$2,$3,$4)' into legacy using _tenant,_account,_from,_to;
  if legacy->'current' is distinct from 'true'::jsonb or legacy->'approved' is distinct from 'true'::jsonb
   or jsonb_typeof(legacy->'blockers') is distinct from 'array' or legacy->'blockers' is distinct from '[]'::jsonb
   then reasons:=array_append(reasons,'legacy_cut_requires_review');end if;
 end if;
 if to_regprocedure('finance_private.account_period_guards_ready()') is not null then execute 'select finance_private.account_period_guards_ready()' into guards;end if;
 if guards is distinct from true then reasons:=array_append(reasons,'period_guards_incomplete');end if;
 if o.id is not null then opening_evidence:=finance_private.statement_period_evidence(_tenant,_account,o.effective_from,o.evidence_to);end if;
 with movements as materialized(select * from public.finance_movements where tenant_id=_tenant and bank_account_id=_account and occurred_on between _from and _to),
 groups as materialized(select g.* from public.finance_reconciliation_groups g where g.tenant_id=_tenant and g.bank_account_id=_account and
  (g.movement_ids&&array(select id from movements) or exists(select 1 from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=any(g.bank_entry_ids) and e.posted_on between _from and _to))),
 active_groups as(select * from groups g where not exists(select 1 from public.finance_reconciliation_reversals r where r.tenant_id=g.tenant_id and r.group_id=g.id)),
 group_members as(select 'movement' kind,unnest(movement_ids) id from active_groups union all select 'bank',unnest(bank_entry_ids) from active_groups)
 select jsonb_build_object('movements',coalesce((select jsonb_agg(to_jsonb(m) order by id) from movements m),'[]'),
  'groups',coalesce((select jsonb_agg(to_jsonb(g) order by id) from groups g),'[]'),
  'group_reversals',coalesce((select jsonb_agg(to_jsonb(r) order by r.id) from public.finance_reconciliation_reversals r join groups g on g.tenant_id=r.tenant_id and g.id=r.group_id),'[]'),
  'duplicate_group_members',(select count(*) from(select kind,id from group_members group by kind,id having count(*)>1)d),
  'pending_jobs',coalesce((select jsonb_agg(to_jsonb(j) order by j.verification_id) from public.finance_automatic_reconciliation_jobs j
    where j.tenant_id=_tenant and j.status='pending' and exists(select 1 from jsonb_array_elements(coverage#>'{dependencies,imports}') imp where imp->>'id'=j.import_id::text)),'[]'),
  'opening_imports',coalesce((select jsonb_agg(to_jsonb(i)-'source_snapshot' order by i.id) from public.finance_statement_imports i where i.tenant_id=_tenant
    and exists(select 1 from jsonb_array_elements(opening_evidence->'anchors') a where a->>'day'=(o.effective_from-1)::text and a->>'import_id'=i.id::text)),'[]'),
  'opening_verifications',coalesce((select jsonb_agg(to_jsonb(v) order by v.id) from public.finance_statement_verifications v where v.tenant_id=_tenant
    and exists(select 1 from jsonb_array_elements(opening_evidence->'anchors') a where a->>'day'=(o.effective_from-1)::text and a->>'verification_id'=v.id::text)),'[]'),
  'transfers',coalesce((select jsonb_agg(to_jsonb(t) order by t.id) from public.finance_internal_transfers t where t.tenant_id=_tenant and exists(select 1 from public.finance_movements m where m.tenant_id=_tenant and m.bank_account_id=_account and m.occurred_on<=_to and m.id in(t.outgoing_id,t.incoming_id))),'[]'),
  'transfer_departures',coalesce((select jsonb_agg(to_jsonb(d) order by d.id) from public.finance_transfer_departures d where d.tenant_id=_tenant and exists(select 1 from public.finance_movements m where m.tenant_id=_tenant and m.occurred_on<=_to and m.id=d.outgoing_id and (m.bank_account_id=_account or d.destination_account_id=_account))),'[]')
 ) into facts;
 if (facts->>'duplicate_group_members')::bigint>0 then reasons:=array_append(reasons,'duplicate_reconciliation_members');end if;
 if jsonb_array_length(facts->'pending_jobs')>0 then reasons:=array_append(reasons,'reconciliation_processing_pending');end if;
 with sources(kind,role,rows) as(values
  ('finance_movements','money',facts->'movements'),('finance_reconciliation_groups','bank_evidence',facts->'groups'),('finance_reconciliation_reversals','bank_evidence',facts->'group_reversals'),
  ('finance_statement_imports','bank_evidence',coverage#>'{dependencies,imports}'),('finance_statement_rows','bank_evidence',coverage#>'{dependencies,rows}'),
  ('finance_statement_verifications','bank_evidence',coverage#>'{dependencies,verifications}'),('finance_bank_entries','money',coverage#>'{dependencies,bank_entries}'),
  ('finance_statement_identity_reviews','bank_evidence',coverage#>'{dependencies,identity_reviews}'),('finance_statement_review_reversals','bank_evidence',coverage#>'{dependencies,identity_reversals}'),
  ('finance_statement_imports','opening',facts->'opening_imports'),('finance_statement_verifications','opening',facts->'opening_verifications'),
  ('finance_account_openings','opening',case when o.id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(o)) end),
  ('finance_account_period_closures','predecessor',case when predecessor.id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(predecessor)-'snapshot') end),
  ('finance_statement_coverage_approvals','bank_evidence',case when coverage->'approval' is null or coverage->'approval'='null'::jsonb then '[]'::jsonb else jsonb_build_array(coverage->'approval') end),
  ('finance_legacy_cut_reviews','legacy_review',case when legacy->>'review_id' is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id',legacy->>'review_id','revision',legacy->>'revision')) end),
  ('finance_internal_transfers','composition_snapshot',facts->'transfers'),('finance_transfer_departures','composition_snapshot',facts->'transfer_departures')
 ), expanded as(select kind,role,row from sources cross join lateral jsonb_array_elements(coalesce(rows,'[]'))row),
 unique_sources as(select distinct on(kind,row->>'id') kind,role,row from expanded order by kind,row->>'id',case role when 'opening' then 0 else 1 end)
 select coalesce(jsonb_agg(jsonb_build_object('source_kind',kind,'source_id',row->>'id','source_revision',md5(row::text),'account_id',_account,
  'affected_from',case when role='opening' then least(_from-1,o.effective_from-1) else _from end,'affected_to',_to,'dependency_role',role) order by kind,row->>'id'),'[]') into dependencies from unique_sources;
 select coalesce(array_agg(distinct reason order by reason),'{}') into reasons from unnest(reasons)reason;
 result:=jsonb_build_object('version',1,'tenant_id',_tenant,'account_id',_account,'from',_from,'to',_to,'currency','BRL','timezone','America/Sao_Paulo',
  'eligible',cardinality(reasons)=0,'blockers',(select coalesce(jsonb_agg(jsonb_build_object('code',r,'source_table',null,'source_ids','[]'::jsonb,'scope','account') order by r),'[]') from unnest(reasons)r),
  'opening_id',o.id,'predecessor_id',predecessor.id,'balances',jsonb_build_object('opening_cents',initial::text,'closing_cents',closing::text,
   'bank_in_cents',review#>>'{bank,in_cents}','bank_out_cents',review#>>'{bank,out_cents}','recorded_in_cents',review#>>'{recorded,in_cents}','recorded_out_cents',review#>>'{recorded,out_cents}'),
  'account',coverage#>'{dependencies,account}','opening',opening,'coverage',coverage,'legacy',legacy,'period_review',review,'facts',facts,'dependencies',dependencies);
 return result||jsonb_build_object('revision',md5(result::text));
end$function$

CREATE OR REPLACE FUNCTION finance_private.apply_payable_movement(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid; actor uuid:=auth.uid();request uuid; cents bigint; payment uuid; link uuid;
 p public.payables%rowtype;m public.finance_movements%rowtype;old_command public.finance_commands%rowtype;
 paid numeric;result jsonb;actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid; request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _payload->>'version' is distinct from '1'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','movement_id','payable_id','amount_cents','method','reason'))
 or coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'method','') not in('pix','boleto','ted','doc','dinheiro','cartao','debito_automatico','other') then
  raise exception 'finance_invalid_payload' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into old_command from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if old_command.actor_id<>actor or old_command.action<>'apply_payable_movement' or old_command.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505';end if;
  return old_command.result;
 end if;
 cents:=(_payload->>'amount_cents')::bigint;
 select * into p from public.payables where id=(_payload->>'payable_id')::uuid and tenant_id=t for update;
 if not found or p.status not in('approved','partial') then raise exception 'finance_payable_not_payable' using errcode='22023';end if;
 select * into m from public.finance_movements where id=(_payload->>'movement_id')::uuid and tenant_id=t;
 if not found or m.direction<>'out' or m.nature='transfer' then raise exception 'finance_invalid_payment_movement' using errcode='22023';end if;
 if p.driver_id is not null and m.driver_id is distinct from p.driver_id then raise exception 'finance_payment_driver_mismatch' using errcode='22023';end if;
 select coalesce(sum(amount),0) into paid from public.payables_payments where tenant_id=t and payable_id=p.id;
 if cents<=0 or paid<0 or paid<>trunc(paid,2) or paid+cents::numeric/100>p.amount then
  raise exception 'finance_payable_overpaid' using errcode='23514';end if;
 if finance_private.movement_used_cents(t,m.id)+cents>m.amount_cents then raise exception 'finance_movement_overallocated' using errcode='23514';end if;
 insert into public.payables_payments(tenant_id,payable_id,amount,paid_at,bank_account_id,method,notes,attachment_url,bank_transaction_id,created_by)
 values(t,p.id,cents::numeric/100,(m.occurred_on+time '12:00') at time zone 'America/Sao_Paulo',m.bank_account_id,
  _payload->>'method',btrim(_payload->>'reason'),m.receipt_path,null,actor) returning id into payment;
 insert into public.finance_payable_movement_links(tenant_id,movement_id,payable_id,payment_id,amount_cents,created_by)
 values(t,m.id,p.id,payment,cents,actor) returning id into link;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'link_id',link,'payment_id',payment,'payable_id',p.id,'movement_id',m.id,'amount_cents',cents::text,'bank_confirmation','not_evaluated');
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(t,'payable_payment',payment,'payable_movement_applied',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),result||jsonb_build_object('manual_intervention',true));
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'apply_payable_movement',_payload,result);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.assert_closed_source_mutable(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid;start_date date;end_date date;ref record;source_table text;source jsonb;identifier uuid;raw_date text;hit boolean:=false;outgoing public.finance_movements%rowtype;incoming public.finance_movements%rowtype;native jsonb;imp public.finance_statement_imports%rowtype;registered public.bank_accounts%rowtype;closed public.finance_account_period_closures%rowtype;anchor date;
begin
 if _row is null or _row='null'::jsonb then return;end if;
 if _table='employee_advances' and _row->>'status' is distinct from 'paid' and _row->>'paid_at' is null then return;end if;
 if _depth>8 then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
 if not finance_private.closed_interval_exists(_tenant,null,null,null) then return;end if;
 identifier:=nullif(_row->>'id','')::uuid;
 if exists(select 1 from public.finance_account_period_dependencies d join public.finance_account_period_closures c on c.tenant_id=d.tenant_id and c.id=d.closure_id where d.tenant_id=_tenant and d.source_kind=_table and d.source_id=identifier and d.dependency_role<>'composition_snapshot' and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
 account:=coalesce(nullif(_row->>'bank_account_id','')::uuid,nullif(_row->>'account_id','')::uuid);
 if account is not null and not exists(select 1 from public.bank_accounts a where a.tenant_id=_tenant and a.id=account) then account:=null;end if; if _table='finance_internal_transfers' then
  select * into outgoing from public.finance_movements where tenant_id=_tenant and id=(_row->>'outgoing_id')::uuid;
  select * into incoming from public.finance_movements where tenant_id=_tenant and id=(_row->>'incoming_id')::uuid;
  -- An already identified departure may arrive later. Its frozen leg stays intact.
  if finance_private.closed_interval_exists(_tenant,outgoing.bank_account_id,outgoing.occurred_on,outgoing.occurred_on) then
   if not exists(select 1 from public.finance_transfer_departures p where p.tenant_id=_tenant and p.outgoing_id=outgoing.id and p.destination_account_id=incoming.bank_account_id
    and not exists(select 1 from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=outgoing.bank_account_id and outgoing.occurred_on between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)
      and (incoming.occurred_on<=c.period_end or not exists(select 1 from public.finance_account_period_dependencies d where d.tenant_id=_tenant and d.closure_id=c.id and d.source_kind='finance_transfer_departures' and d.source_id=p.id)))) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',to_jsonb(incoming),_depth+1);return;
  end if;
 end if;
 if _table='finance_statement_verifications' then
  select * into imp from public.finance_statement_imports where tenant_id=_tenant and id=(_row->>'import_id')::uuid;
  native:=_row#>'{report,native_evidence}';
  if native is not null then
   if finance_private.closed_interval_exists(_tenant,imp.bank_account_id,(native#>>'{period,start,date}')::date,(native#>>'{period,end,date}')::date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   anchor:=(native#>>'{ledger_balance,as_of,date}')::date;
   for closed in select c.* from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=imp.bank_account_id and anchor between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id) loop
    select * into registered from public.bank_accounts where tenant_id=_tenant and id=imp.bank_account_id;
    if anchor is distinct from closed.period_end or native#>>'{ledger_balance,amount_cents}' is distinct from closed.snapshot#>>'{balances,closing_cents}'
     or native#>>'{ledger_balance,as_of,offset_minutes}' is distinct from '-180' or native#>>'{period,start,offset_minutes}' is distinct from '-180' or native#>>'{period,end,offset_minutes}' is distinct from '-180'
     or native->>'currency' is distinct from 'BRL' or native->>'parser_version' is distinct from 'native-ofx-v1'
     or native#>>'{account,bank_id}' is distinct from btrim(registered.bank_code) or native#>>'{account,branch_id}' is distinct from btrim(registered.branch_number) or native#>>'{account,account_id}' is distinct from btrim(registered.account_number)
     or native#>>'{account,account_type}' is distinct from (case registered.account_type when 'checking' then 'CHECKING' when 'savings' then 'SAVINGS' end)
     or _row->>'outcome' is distinct from 'rows_match' or _row#>>'{report,hash_verified}' is distinct from 'true' or _row#>>'{report,actual_hash}' is distinct from imp.file_hash or _row#>>'{report,identity_trust}' is distinct from 'native_file_identifier'
     or native->>'outside_declared_period' is distinct from 'false' or native->'repeated_bank_ids' is distinct from '[]'::jsonb
    then raise exception 'finance_closed_anchor_conflict' using errcode='55000';end if;
   end loop;
  end if;
 end if;
 if _table in('finance_statement_imports','finance_statement_coverage_approvals','finance_period_evidence_reviews','finance_legacy_cut_reviews') then
  start_date:=(_row->>'period_start')::date;end_date:=(_row->>'period_end')::date;
 elsif _table='finance_account_openings' then start_date:=(_row->>'effective_from')::date;end_date:=null;
 else
  raw_date:=coalesce(_row->>'occurred_on',_row->>'posted_on',_row->>'posted_at',_row->>'received_at',_row->>'paid_at',_row->>'effective_at',_row->>'payment_date',_row->>'advance_date',_row->>'occurred_at',_row->>'competence_date');
  if raw_date is not null then start_date:=(raw_date::timestamptz at time zone 'America/Sao_Paulo')::date;
   if raw_date ~ '^\d{4}-\d{2}-\d{2}$' then start_date:=raw_date::date;end if;end_date:=start_date;end if;
 end if;
 if start_date is not null or _table in('finance_movements','finance_bank_entries','bank_transactions','receivables_payments','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items') then
  if finance_private.closed_interval_exists(_tenant,account,start_date,end_date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
  hit:=true;
 end if;
 for ref in select key,value from jsonb_each_text(_row) where key in('import_id','first_import_id','row_id','review_id','group_id','opening_id','approval_id','bank_transaction_id','bank_entry_id','movement_id','outgoing_id','incoming_id','receivable_payment_id','payment_id') and value is not null loop
  source_table:=case ref.key when 'import_id' then case when _table='bank_transactions' then null else 'finance_statement_imports' end when 'first_import_id' then 'finance_statement_imports' when 'row_id' then 'finance_statement_rows' when 'review_id' then 'finance_statement_identity_reviews' when 'group_id' then 'finance_reconciliation_groups' when 'opening_id' then 'finance_account_openings' when 'approval_id' then 'finance_statement_coverage_approvals' when 'bank_transaction_id' then 'bank_transactions' when 'bank_entry_id' then 'finance_bank_entries' when 'movement_id' then 'finance_movements' when 'outgoing_id' then 'finance_movements' when 'incoming_id' then 'finance_movements' when 'receivable_payment_id' then 'receivables_payments' when 'payment_id' then case when _table='receivable_payment_reversals' then 'receivables_payments' end end;
  if source_table is not null then
   if _table='receivable_payment_reversals' and ref.key='payment_id' and start_date is not null then continue;end if;
   execute format('select to_jsonb(s) from public.%I s where s.tenant_id=$1 and s.id=$2',source_table) into source using _tenant,ref.value::uuid;
   if source is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,source_table,source,_depth+1);hit:=true;
  end if;
 end loop;
 if _table='finance_reconciliation_groups' then
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'movement_ids') loop select to_jsonb(m) into source from public.finance_movements m where m.tenant_id=_tenant and m.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',source,_depth+1);end loop;
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'bank_entry_ids') loop select to_jsonb(e) into source from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_bank_entries',source,_depth+1);end loop;hit:=true;
 end if;
 if not hit then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
end$function$

CREATE OR REPLACE FUNCTION finance_private.cash_period_close_snapshot(_tenant uuid, _account uuid, _from date, _to date, _count uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account public.bank_accounts%rowtype;o public.finance_account_openings%rowtype;pred public.finance_account_period_closures%rowtype;c public.finance_cash_period_counts%rowtype;
 legacy jsonb;facts jsonb;dependencies jsonb;result jsonb;reasons text[]:='{}';initial numeric;inflow numeric;outflow numeric;expected numeric;counted numeric;difference numeric;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _from is null or _to is null or not isfinite(_from) or not isfinite(_to) or _from>_to or _to-_from>=366 then raise exception 'finance_invalid_filters' using errcode='22023';end if;
 select * into account from public.bank_accounts where tenant_id=_tenant and id=_account;if not found then raise exception 'finance_account_not_found' using errcode='22023';end if;
 if account.account_type is distinct from 'cash' or not account.active then reasons:=array_append(reasons,'cash_account_required');end if;
 if _to>=(clock_timestamp() at time zone 'America/Sao_Paulo')::date then reasons:=array_append(reasons,'period_not_ended');end if;
 select * into o from public.finance_account_openings op where tenant_id=_tenant and bank_account_id=_account and not exists(select 1 from public.finance_account_opening_reversals r where r.tenant_id=_tenant and r.opening_id=op.id);
 if o.id is null or o.evidence_type is distinct from 'cash_count_v1' or not finance_private.cash_opening_evidence_valid(o.evidence,o.effective_from,o.balance_cents) then reasons:=array_append(reasons,'cash_opening_requires_review');end if;
 select * into pred from public.finance_account_period_closures cl where tenant_id=_tenant and account_id=_account and period_end<_from and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=_tenant and r.closure_id=cl.id) order by period_end desc,id limit 1;
 if exists(select 1 from public.finance_account_period_closures cl where tenant_id=_tenant and account_id=_account and period_start<=_to and period_end>=_from and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=_tenant and r.closure_id=cl.id)) then reasons:=array_append(reasons,'period_already_closed');end if;
 if pred.id is null then initial:=o.balance_cents;if o.effective_from is distinct from _from then reasons:=array_append(reasons,'period_must_start_at_opening');end if;
 else initial:=(pred.snapshot#>>'{balances,closing_cents}')::numeric;if pred.period_end+1<>_from or pred.opening_id is distinct from o.id or pred.snapshot->>'evidence_type' is distinct from 'cash_count_v1' then reasons:=array_append(reasons,'predecessor_not_contiguous');end if;end if;
 select * into c from public.finance_cash_period_counts where tenant_id=_tenant and id=_count;
 if c.id is null or c.account_id is distinct from _account or c.period_end is distinct from _to or exists(select 1 from public.finance_cash_period_count_reversals where tenant_id=_tenant and count_id=c.id) then reasons:=array_append(reasons,'cash_count_requires_review');
 elsif c.revision is distinct from md5((to_jsonb(c)-'revision')::text) or finance_private.cash_count_total(c.counts)<>c.total_cents then reasons:=array_append(reasons,'cash_count_integrity_failure');
 else counted:=c.total_cents;end if;
 select coalesce(sum(amount_cents) filter(where direction='in'),0),coalesce(sum(amount_cents) filter(where direction='out'),0) into inflow,outflow from public.finance_movements where tenant_id=_tenant and bank_account_id=_account and occurred_on between _from and _to;
 expected:=initial+inflow-outflow;difference:=counted-expected;
 if difference is null or difference<>0 then reasons:=array_append(reasons,'cash_count_difference');end if;
 if expected<0 then reasons:=array_append(reasons,'cash_negative_position');end if;
 if exists(select 1 from public.finance_bank_entries where tenant_id=_tenant and bank_account_id=_account) or exists(select 1 from public.finance_statement_imports where tenant_id=_tenant and bank_account_id=_account) then reasons:=array_append(reasons,'cash_has_bank_evidence_anomaly');end if;
 legacy:=finance_private.legacy_cut_review_status(_tenant,_account,_from,_to);
 if legacy->'approved' is distinct from 'true'::jsonb or legacy->'current' is distinct from 'true'::jsonb or legacy->'blockers' is distinct from '[]'::jsonb then reasons:=array_append(reasons,'legacy_cut_requires_review');end if;
 if not finance_private.cash_period_guards_ready() then reasons:=array_append(reasons,'closed_period_guards_incomplete');end if;
 facts:=jsonb_build_object('movements',(select coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]') from public.finance_movements m where m.tenant_id=_tenant and m.bank_account_id=_account and m.occurred_on between _from and _to),
 'transfers',(select coalesce(jsonb_agg(to_jsonb(tr) order by tr.id),'[]') from public.finance_internal_transfers tr where tr.tenant_id=_tenant and exists(select 1 from public.finance_movements m where m.tenant_id=_tenant and m.bank_account_id=_account and m.occurred_on between _from and _to and m.id in(tr.outgoing_id,tr.incoming_id))),
 'transfer_departures',(select coalesce(jsonb_agg(to_jsonb(d) order by d.id),'[]') from public.finance_transfer_departures d where d.tenant_id=_tenant and exists(select 1 from public.finance_movements m where m.tenant_id=_tenant and m.bank_account_id=_account and m.occurred_on between _from and _to and m.id=d.outgoing_id)));
 with sources(kind,role,rows) as(values
 ('finance_movements','money',facts->'movements'),('finance_internal_transfers','composition_snapshot',facts->'transfers'),('finance_transfer_departures','composition_snapshot',facts->'transfer_departures'),
 ('finance_cash_period_counts','cash_evidence',case when c.id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(c)) end),
 ('finance_account_openings','opening',case when o.id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(o)) end),
 ('finance_account_period_closures','predecessor',case when pred.id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(pred)-'snapshot') end),
 ('finance_legacy_cut_reviews','legacy_review',case when legacy->>'review_id' is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id',legacy->>'review_id','revision',legacy->>'revision')) end)),
 expanded as(select kind,role,row from sources cross join lateral jsonb_array_elements(rows) row)
 select coalesce(jsonb_agg(jsonb_build_object('source_kind',kind,'source_id',row->>'id','source_revision',md5(row::text),'account_id',_account,'affected_from',_from,'affected_to',_to,'dependency_role',role) order by kind,row->>'id'),'[]') into dependencies from expanded;
 result:=jsonb_build_object('version',1,'tenant_id',_tenant,'account_id',_account,'from',_from,'to',_to,'currency','BRL','timezone','America/Sao_Paulo','evidence_type','cash_count_v1','eligible',cardinality(reasons)=0,
 'blockers',(select coalesce(jsonb_agg(jsonb_build_object('code',reason,'source_table',null,'source_ids','[]'::jsonb,'scope','account') order by reason),'[]') from unnest(reasons) reason),
 'opening_id',o.id,'predecessor_id',pred.id,'account',to_jsonb(account),'opening',case when o.id is null then null else to_jsonb(o) end,'predecessor',case when pred.id is null then null else to_jsonb(pred)-'snapshot' end,
 'count',case when c.id is null then null else to_jsonb(c)||jsonb_build_object('total_cents',c.total_cents::text) end,'legacy',legacy,
 'balances',jsonb_build_object('opening_cents',trunc(initial)::text,'in_cents',trunc(inflow)::text,'out_cents',trunc(outflow)::text,'expected_closing_cents',trunc(expected)::text,'counted_closing_cents',trunc(counted)::text,'difference_cents',trunc(difference)::text,'closing_cents',trunc(counted)::text),
 'facts',facts,'dependencies',dependencies);
 return result||jsonb_build_object('revision',md5(result::text));
end$function$

CREATE OR REPLACE FUNCTION finance_private.late_payment_composition_proved(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb;link record;m public.finance_movements%rowtype;amount numeric;day date;account uuid;matches integer:=0;identifier uuid;used numeric;
begin
 if _depth>3 then return false;end if;
 identifier:=(_row->>'id')::uuid;amount:=(_row->>'amount')::numeric*100;
 if not coalesce(amount>0 and amount=trunc(amount) and amount<=99999999999999,false) then return false;end if;
 account:=(_row->>'bank_account_id')::uuid;
 day:=case when _table in('load_payments','closing_report_payments') then (_row->>'payment_date')::date else (coalesce(_row->>'received_at',_row->>'paid_at',_row->>'posted_at')::timestamptz at time zone 'America/Sao_Paulo')::date end;
 if day is null or not isfinite(day) then return false;end if;
 if _table in('load_payments','closing_report_payments') then
  select to_jsonb(p) into source from public.receivables_payments p where p.tenant_id=_tenant and p.id=(case when _table='load_payments' then _row->>'receivable_payment_id' else _row->>'canonical_receivable_payment_id' end)::uuid;
  return source is not null and source->>'receivable_id' is not distinct from _row->>'receivable_id' and (source->>'amount')::numeric*100=amount and source->>'bank_account_id' is not distinct from _row->>'bank_account_id'
   and ((source->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date=day and finance_private.late_payment_composition_proved(_tenant,'receivables_payments',source,_depth+1);
 elsif _table='bank_transactions' then
  for link in select l.* from public.finance_receivable_movement_links l where l.tenant_id=_tenant and l.bank_transaction_id=identifier and l.action='receive' loop
   select to_jsonb(p) into source from public.receivables_payments p where p.tenant_id=_tenant and p.id=link.payment_id and p.financial_command_id=link.command_id and p.bank_transaction_id=identifier;
   if source is not null and _row->>'transaction_type'='credit' and (source->>'amount')::numeric*100=amount and source->>'bank_account_id'=_row->>'bank_account_id'
    and ((source->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date=day and finance_private.late_payment_composition_proved(_tenant,'receivables_payments',source,_depth+1) then matches:=matches+1;end if;
  end loop;return matches=1;
 elsif _table='receivables_payments' then
  if exists(select 1 from public.finance_receipt_allocation_corrections c where c.tenant_id=_tenant and c.payment_id=identifier) then return false;end if;
  for link in select l.* from public.finance_receivable_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.action='receive' and l.command_id=(_row->>'financial_command_id')::uuid and l.bank_transaction_id=(_row->>'bank_transaction_id')::uuid loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='in' and m.bank_account_id=account and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.receipt_movement_used_cents(_tenant,m.id);
    if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 elsif _table='payables_payments' then
  if _row->>'bank_transaction_id' is not null then return false;end if;
  for link in select l.* from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.payable_id=(_row->>'payable_id')::uuid and l.origin='canonical' and l.amount_cents=amount and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id) loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='out' and m.bank_account_id=account and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.movement_used_cents(_tenant,m.id);if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 elsif _table='driver_settlement_payments' then
  for link in select l.* from public.finance_settlement_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.settlement_id=(_row->>'settlement_id')::uuid and l.amount_cents=amount and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id) loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='out' and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.movement_used_cents(_tenant,m.id);if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 end if;
 return false;
end$function$

CREATE OR REPLACE FUNCTION finance_private.legacy_cut_manifest(_tenant uuid, _account uuid, _from date, _to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sources jsonb:='[]';evidence jsonb:='{}';blockers jsonb:='[]';rows_json jsonb;item jsonb;entry jsonb;integrity jsonb;r record;
 driver_map jsonb;projection jsonb;footprint jsonb;projection_slice jsonb;classification text;table_name text;resolved jsonb;new_sources jsonb:='[]';day date;account uuid;amount numeric;movement_ids jsonb;m record;valid boolean;manifest jsonb;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _from is null or _to is null or not isfinite(_from) or not isfinite(_to) or _from>_to or _to-_from>365 then raise exception 'finance_invalid_filters' using errcode='22023';end if;
 if not exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=_account) then raise exception 'finance_account_not_found' using errcode='22023';end if;
 -- Every included family is explicit, including zero counts. No page or LIMIT.
 foreach table_name in array array['receivables_payments','receivable_payment_reversals','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items','bank_transactions','finance_movements','finance_receivable_movement_links','finance_payable_movement_links','finance_payable_link_reversals','finance_settlement_movement_links','finance_settlement_link_reversals','finance_legacy_receipt_movement_links','finance_legacy_receipt_link_reversals','finance_receipt_allocation_corrections','finance_expense_allocations','driver_settlements','employees','payables','payroll_entries','payroll_periods','financial_obligations'] loop
  execute format('select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]'') from public.%I x where tenant_id=$1',table_name) into rows_json using _tenant;
  evidence:=evidence||jsonb_build_object(table_name,rows_json);
 end loop;
 select coalesce(jsonb_agg(to_jsonb(x) order by source_table,source_id),'[]') into integrity from finance_private.legacy_integrity_rows(_tenant) x;
 foreach table_name in array array['receivables_payments','receivable_payment_reversals','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items','bank_transactions'] loop
  for item in select value from jsonb_array_elements(evidence->table_name) loop
   if table_name='employee_advances' and item->>'status' is distinct from 'paid' then continue;end if;
   if table_name='payroll_entry_items' and item->>'nature' is distinct from 'already_paid' then continue;end if;
   if table_name in('employee_advances','payroll_entry_items') then
    projection:=finance_private.paid_projection_chain(_tenant,table_name,(item->>'id')::uuid);
    if projection->'valid'='true'::jsonb then
     select coalesce(jsonb_agg(f order by f->>'movement_id',f->>'payment_id'),'[]') into projection_slice from jsonb_array_elements(projection->'footprints') f where f->>'account_id'=_account::text and (f->>'occurred_on')::date between _from and _to;
     if jsonb_array_length(projection_slice)>0 then
      sources:=sources||jsonb_build_array(jsonb_build_object('source_table',table_name,'source_id',item->>'id','occurred_on',null,'account_id',_account,'amount_cents',null,'movement_ids',(select jsonb_agg(distinct f->>'movement_id') from jsonb_array_elements(projection_slice) f),'classification','exact_projection_alias','footprints',projection_slice,'chain_revision',projection->>'revision'));
     end if;
    else
     sources:=sources||jsonb_build_array(jsonb_build_object('source_table',table_name,'source_id',item->>'id','occurred_on',null,'account_id',null,'amount_cents',null,'movement_ids','[]'::jsonb,'classification','requires_resolution','footprints',projection->'footprints','chain_revision',projection->>'revision'));
     blockers:=blockers||jsonb_build_array(jsonb_build_object('code',coalesce(projection->>'issue','paid_projection_unresolved'),'source_table',table_name,'source_id',item->>'id'));
    end if;
    evidence:=evidence||jsonb_build_object('paid_projection_chain:'||table_name||':'||(item->>'id'),jsonb_build_array(projection));
    continue;
   end if;
   day:=case table_name when 'receivables_payments' then ((item->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date when 'receivable_payment_reversals' then ((item->>'effective_at')::timestamptz at time zone 'America/Sao_Paulo')::date when 'bank_transactions' then ((item->>'posted_at')::timestamptz at time zone 'America/Sao_Paulo')::date when 'closing_report_payments' then (item->>'payment_date')::date when 'load_payments' then (item->>'payment_date')::date when 'payroll_entry_items' then coalesce(((item->>'occurred_at')::timestamptz at time zone 'America/Sao_Paulo')::date,(item->>'competence_date')::date) else coalesce(((item->>'paid_at')::timestamptz at time zone 'America/Sao_Paulo')::date,(item->>'advance_date')::date) end;
   account:=(item->>'bank_account_id')::uuid;amount:=(item->>'amount')::numeric*100;movement_ids:='[]';
   -- Refund money belongs to its own exact bank leg, never the incoming parent account.
   if table_name='receivable_payment_reversals' then select bank_account_id into account from public.bank_transactions where tenant_id=_tenant and id=(item->>'bank_transaction_id')::uuid;end if;
   if table_name='driver_settlement_payments' then driver_map:=finance_private.legacy_cut_settlement_evidence(_tenant,(item->>'id')::uuid);account:=(driver_map->>'account_id')::uuid;end if;
   if account is not null and exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=account) and account<>_account then continue;end if;
   if day is not null and isfinite(day) and (day<_from or day>_to) then continue;end if;
   valid:=false;classification:='requires_resolution';
   if table_name in('receivables_payments','payables_payments','receivable_payment_reversals') and amount>0 and amount=trunc(amount) and amount<=99999999999999 and day is not null and isfinite(day) then
    for m in
     select value link from jsonb_array_elements(case table_name when 'payables_payments' then evidence->'finance_payable_movement_links' else evidence->'finance_receivable_movement_links' end)
     where value->>'payment_id'=case when table_name='receivable_payment_reversals' then item->>'payment_id' else item->>'id' end
     and (table_name='payables_payments' or value->>'action'=case when table_name='receivable_payment_reversals' then 'reverse' else 'receive' end)
     and (table_name<>'payables_payments' or value->>'payable_id'=item->>'payable_id')
     and (table_name='payables_payments' or (value->>'command_id'=item->>'financial_command_id' and value->>'bank_transaction_id'=item->>'bank_transaction_id'))
    loop
     select * into r from public.finance_movements where tenant_id=_tenant and id=(m.link->>'movement_id')::uuid;
     if found and r.bank_account_id=account and r.occurred_on=day and r.direction=(case when table_name='receivables_payments' then 'in' else 'out' end) and r.amount_cents>=amount
       and (table_name<>'payables_payments' or ((m.link->>'amount_cents')::numeric=amount and (coalesce(m.link->>'origin','canonical')='canonical' or not exists(select 1 from public.finance_payable_link_reversals where tenant_id=_tenant and link_id=(m.link->>'id')::uuid)))) then movement_ids:=movement_ids||jsonb_build_array(r.id);end if;
    end loop;
    if table_name='receivables_payments' then
     for m in select value link from jsonb_array_elements(evidence->'finance_legacy_receipt_movement_links') where value->>'payment_id'=item->>'id' and (value->>'amount_cents')::numeric=amount and value->>'receivable_id'=item->>'receivable_id' and not exists(select 1 from public.finance_legacy_receipt_link_reversals where tenant_id=_tenant and link_id=(value->>'id')::uuid) loop
      select * into r from public.finance_movements where tenant_id=_tenant and id=(m.link->>'movement_id')::uuid;
      if found and r.bank_account_id=account and r.occurred_on=day and r.direction='in' and r.amount_cents>=amount then movement_ids:=movement_ids||jsonb_build_array(r.id);end if;
     end loop;
    end if;
    valid:=jsonb_array_length(movement_ids)=1;
   end if;
   if table_name='driver_settlement_payments' then valid:=coalesce((driver_map->>'valid')::boolean,false);movement_ids:=driver_map->'movement_ids';end if;
   if valid then
    classification:='exact_canonical_mapping';
    if table_name='receivables_payments' and exists(select 1 from public.finance_receipt_allocation_corrections c where c.tenant_id=_tenant and c.payment_id=(item->>'id')::uuid and c.receivable_id=(item->>'receivable_id')::uuid and c.movement_id=(movement_ids->>0)::uuid) then classification:='corrected_receipt_projection';end if;
    if table_name='payables_payments' and exists(select 1 from jsonb_array_elements(evidence->'finance_payable_movement_links') l join public.finance_payable_link_reversals rv on rv.tenant_id=_tenant and rv.link_id=(l->>'id')::uuid where l->>'payment_id'=item->>'id' and coalesce(l->>'origin','canonical')='canonical') then classification:='reversed_canonical_payment_projection';end if;
   end if;
   entry:=jsonb_build_object('source_table',table_name,'source_id',item->>'id','occurred_on',case when isfinite(day) then day end,'account_id',account,'amount_cents',case when amount>0 and amount=trunc(amount) and amount<=99999999999999 then trunc(amount)::text end,'movement_ids',movement_ids,'classification',classification);
   if exists(select 1 from jsonb_array_elements(integrity) x where x->>'source_table'=table_name and x->>'source_id'=item->>'id') then valid:=false;entry:=entry||jsonb_build_object('classification','integrity_failure');end if;
   sources:=sources||jsonb_build_array(entry);
   if not valid then blockers:=blockers||jsonb_build_array(jsonb_build_object('code',case when day is null or not isfinite(day) then 'legacy_source_date_unknown' when account is null or not exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=account) then 'legacy_source_account_unknown' else 'legacy_source_requires_resolution' end,'source_table',table_name,'source_id',item->>'id'));end if;
  end loop;
 end loop;
 -- Resolve only aliases whose exact parent is already validated; never compare descriptions.
 for entry in select value from jsonb_array_elements(sources) loop
  if entry->>'source_table' in('bank_transactions','load_payments','closing_report_payments') and entry->>'classification'='requires_resolution' then
   select value into item from jsonb_array_elements(evidence->(entry->>'source_table')) where value->>'id'=entry->>'source_id';
   select coalesce(jsonb_agg(src),'[]') into resolved from jsonb_array_elements(sources) src
   where src->>'classification' in('exact_canonical_mapping','corrected_receipt_projection','reversed_canonical_payment_projection') and src->>'source_table' in('receivables_payments','payables_payments','receivable_payment_reversals')
   and src->>'amount_cents'=entry->>'amount_cents' and src->>'account_id'=entry->>'account_id' and src->>'occurred_on'=entry->>'occurred_on'
   and exists(select 1 from jsonb_array_elements(evidence->(src->>'source_table')) raw where raw->>'id'=src->>'source_id' and
    (case when entry->>'source_table'='bank_transactions' then raw->>'bank_transaction_id'=item->>'id'
     when entry->>'source_table'='load_payments' then src->>'source_table'='receivables_payments' and raw->>'id'=item->>'receivable_payment_id'
     else src->>'source_table'='receivables_payments' and raw->>'id'=item->>'canonical_receivable_payment_id' end));
   if jsonb_array_length(resolved)=1 then entry:=entry||jsonb_build_object('classification','exact_projection_alias','movement_ids',resolved->0->'movement_ids');end if;
  end if;
  new_sources:=new_sources||jsonb_build_array(entry);
 end loop;
 sources:=new_sources;
 select coalesce(jsonb_agg(b),'[]') into blockers from jsonb_array_elements(blockers) b where not exists(select 1 from jsonb_array_elements(sources) x where x->>'source_table'=b->>'source_table' and x->>'source_id'=b->>'source_id' and x->>'classification'='exact_projection_alias');
 -- Shared movement capacity counts direct money once, excluding projection aliases.
 for m in select movement.value->>0 id,sum((src->>'amount_cents')::numeric) used from jsonb_array_elements(sources) src cross join lateral (select src->'movement_ids' value) movement where src->>'classification'='exact_canonical_mapping' group by movement.value->>0 loop
  if m.used>(select amount_cents from public.finance_movements where tenant_id=_tenant and id=m.id::uuid) then blockers:=blockers||jsonb_build_array(jsonb_build_object('code','legacy_mapping_capacity_exceeded','source_table','finance_movements','source_id',m.id));end if;
 end loop;
 manifest:=jsonb_build_object('version',1,'classifier_version','3','tenant_id',_tenant,'account_id',_account,'from',_from,'to',_to,'sources',sources,'evidence',evidence,'integrity',integrity,'blockers',blockers,'source_count',jsonb_array_length(sources));
 return manifest||jsonb_build_object('revision',md5(manifest::text));
end$function$

CREATE OR REPLACE FUNCTION finance_private.legacy_cut_settlement_evidence(_tenant uuid, _payment uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.driver_settlement_payments%rowtype;s public.driver_settlements%rowtype;l public.finance_settlement_movement_links%rowtype;m public.finance_movements%rowtype;n integer;used numeric;valid boolean:=false;
begin
 select * into p from public.driver_settlement_payments where tenant_id=_tenant and id=_payment;
 if not found then return jsonb_build_object('valid',false,'account_id',null,'movement_ids','[]'::jsonb);end if;
 select count(*) into n from public.finance_settlement_movement_links x where x.tenant_id=_tenant and x.payment_id=p.id and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=_tenant and r.link_id=x.id);
 if n<>1 then return jsonb_build_object('valid',false,'account_id',null,'movement_ids','[]'::jsonb);end if;
 select * into l from public.finance_settlement_movement_links x where x.tenant_id=_tenant and x.payment_id=p.id and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=_tenant and r.link_id=x.id);
 select * into s from public.driver_settlements where tenant_id=_tenant and id=p.settlement_id;
 select * into m from public.finance_movements where tenant_id=_tenant and id=l.movement_id;
 if not found then return jsonb_build_object('valid',false,'account_id',null,'movement_ids','[]'::jsonb);end if;
 select coalesce(sum(cents),0) into used from (
  select a.amount_cents cents from public.finance_expense_allocations a where a.tenant_id=_tenant and a.movement_id=m.id
  union all select a.amount_cents from public.finance_payable_movement_links a where a.tenant_id=_tenant and a.movement_id=m.id and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=a.id)
  union all select a.amount_cents from public.finance_settlement_movement_links a where a.tenant_id=_tenant and a.movement_id=m.id and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=_tenant and r.link_id=a.id)
 ) allocations;
 valid:=coalesce(s.id is not null and s.driver_id is not null and exists(select 1 from public.drivers where tenant_id=_tenant and id=s.driver_id) and l.settlement_id=p.settlement_id and m.driver_id=s.driver_id and m.direction='out' and m.nature<>'transfer'
  and p.amount>0 and p.amount*100=trunc(p.amount*100) and p.amount*100<=99999999999999 and l.amount_cents=p.amount*100
  and p.paid_at is not null and isfinite(p.paid_at) and m.occurred_on=(p.paid_at at time zone 'America/Sao_Paulo')::date
  and used<=m.amount_cents and exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=m.bank_account_id),false);
 return jsonb_build_object('valid',valid,'account_id',case when valid then m.bank_account_id end,'movement_ids',case when valid then jsonb_build_array(m.id) else '[]'::jsonb end,'link_id',l.id,'reserved_cents',used::text);
end$function$

CREATE OR REPLACE FUNCTION finance_private.legacy_integrity_rows(_tenant uuid)
 RETURNS TABLE(source_table text, source_id uuid, date_status text, occurred_on text, raw_date text, account_id uuid, account_status text, amount_cents text, raw_amount text, direction text, issues text[], context jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r record;s jsonb;parent jsonb;bank jsonb;alias_row jsonb;reference_row jsonb;ref record;
 d date; cents numeric;parent_table text;parent_key text;alias_key text;bank_id text;money boolean;
begin
 for r in
  select 'receivables_payments'::text kind,to_jsonb(x) payload,(x.received_at at time zone 'America/Sao_Paulo')::date as source_day,x.received_at::text date_text from public.receivables_payments x where tenant_id=_tenant
  union all select 'receivable_payment_reversals',to_jsonb(x),(x.effective_at at time zone 'America/Sao_Paulo')::date,x.effective_at::text from public.receivable_payment_reversals x where tenant_id=_tenant
  union all select 'payables_payments',to_jsonb(x),(x.paid_at at time zone 'America/Sao_Paulo')::date,x.paid_at::text from public.payables_payments x where tenant_id=_tenant
  union all select 'driver_settlement_payments',to_jsonb(x),(x.paid_at at time zone 'America/Sao_Paulo')::date,x.paid_at::text from public.driver_settlement_payments x where tenant_id=_tenant
  union all select 'closing_report_payments',to_jsonb(x),x.payment_date,x.payment_date::text from public.closing_report_payments x where tenant_id=_tenant
  union all select 'load_payments',to_jsonb(x),x.payment_date,x.payment_date::text from public.load_payments x where tenant_id=_tenant
  union all select 'employee_advances',to_jsonb(x),coalesce((x.paid_at at time zone 'America/Sao_Paulo')::date,x.advance_date),coalesce(x.paid_at::text,x.advance_date::text) from public.employee_advances x where tenant_id=_tenant and status='paid'
  union all select 'payroll_entry_items',to_jsonb(x),coalesce((x.occurred_at at time zone 'America/Sao_Paulo')::date,x.competence_date),coalesce(x.occurred_at::text,x.competence_date::text) from public.payroll_entry_items x where tenant_id=_tenant and nature='already_paid'
  union all select 'bank_transactions',to_jsonb(x),(x.posted_at at time zone 'America/Sao_Paulo')::date,x.posted_at::text from public.bank_transactions x where tenant_id=_tenant
 loop
  s:=r.payload;source_table:=r.kind;source_id:=(s->>'id')::uuid;d:=r.source_day;raw_date:=r.date_text;
  issues:='{}';context:='{}';account_id:=(s->>'bank_account_id')::uuid;raw_amount:=s->>'amount';amount_cents:=null;
  date_status:=case when d is null then 'missing' when not isfinite(d) then 'nonfinite' else 'valid' end;
  occurred_on:=case when date_status='valid' then to_char(d,'YYYY-MM-DD') end;
  if date_status<>'valid' then issues:=array_append(issues,'date_'||date_status);end if;
  direction:=case when source_table in ('receivables_payments','closing_report_payments','load_payments') then 'in' when source_table='bank_transactions' then case s->>'transaction_type' when 'credit' then 'in' when 'debit' then 'out' else 'unknown' end when source_table='payroll_entry_items' then 'unknown' else 'out' end;
  money:=source_table not in ('employee_advances','payroll_entry_items');
  cents:=case when raw_amount is not null then raw_amount::numeric*100 end;
  if cents>0 and cents=trunc(cents) and cents<=99999999999999 then
   if money then amount_cents:=trunc(cents)::text;end if;
  else issues:=array_append(issues,'amount_invalid');end if;
  if direction='unknown' and source_table='bank_transactions' then issues:=array_append(issues,'direction_unknown');end if;
  parent_table:=case source_table when 'receivables_payments' then 'receivables' when 'receivable_payment_reversals' then 'receivables_payments' when 'payables_payments' then 'payables' when 'driver_settlement_payments' then 'driver_settlements' when 'closing_report_payments' then 'closing_reports' when 'load_payments' then 'loads' when 'employee_advances' then 'employees' when 'payroll_entry_items' then 'payroll_entries' end;
  parent_key:=case source_table when 'receivables_payments' then 'receivable_id' when 'receivable_payment_reversals' then 'payment_id' when 'payables_payments' then 'payable_id' when 'driver_settlement_payments' then 'settlement_id' when 'closing_report_payments' then 'closing_report_id' when 'load_payments' then 'load_id' when 'employee_advances' then 'employee_id' when 'payroll_entry_items' then 'payroll_entry_id' end;
  parent:=null;
  if parent_table is not null then
   parent:=finance_private.legacy_integrity_reference(_tenant,parent_table,s->>parent_key);
   context:=context||jsonb_build_object('parent_table',parent_table,'parent_id',s->parent_key);
   if parent is null then issues:=array_append(issues,'parent_not_in_tenant');end if;
  end if;
  if source_table='receivable_payment_reversals' then account_id:=(parent->>'bank_account_id')::uuid;end if;
  -- Only an exact active canonical association can supply the account for a settlement.
  if source_table='driver_settlement_payments' then
   select m.bank_account_id into account_id from public.finance_settlement_movement_links l join public.finance_movements m on m.tenant_id=l.tenant_id and m.id=l.movement_id where l.tenant_id=_tenant and l.payment_id=source_id and not exists(select 1 from public.finance_settlement_link_reversals z where z.tenant_id=l.tenant_id and z.link_id=l.id) order by l.id limit 1;
  end if;
  account_status:=case when account_id is null then 'unresolved' when exists(select 1 from public.bank_accounts a where a.tenant_id=_tenant and a.id=account_id) then 'identified' else 'not_in_tenant' end;
  -- Projection rows are not independent cash and lack a direct account by design.
  if account_status<>'identified' and money then issues:=array_append(issues,'account_'||account_status);end if;
  if source_table in ('closing_report_payments','load_payments') then
   alias_key:=case source_table when 'load_payments' then 'receivable_payment_id' else 'canonical_receivable_payment_id' end;
   alias_row:=finance_private.legacy_integrity_reference(_tenant,'receivables_payments',s->>alias_key);
   context:=context||jsonb_build_object('receipt_id',s->alias_key);
   if alias_row is null then issues:=array_append(issues,'receipt_alias_missing');
   elsif (alias_row->>'amount')::numeric is distinct from (s->>'amount')::numeric or alias_row->>'bank_account_id' is distinct from s->>'bank_account_id' or ((alias_row->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date is distinct from d or (s->>'receivable_id' is not null and s->>'receivable_id' is distinct from alias_row->>'receivable_id') or (s->>'bank_transaction_id' is not null and s->>'bank_transaction_id' is distinct from alias_row->>'bank_transaction_id') then issues:=array_append(issues,'receipt_alias_mismatch');end if;
  end if;
  if source_table='payroll_entry_items' then
   reference_row:=finance_private.legacy_integrity_reference(_tenant,s->>'source_table',s->>'source_id');
   if s->>'source_table' not in ('driver_settlement_payments','employee_advances','payables_payments') or reference_row is null then issues:=array_append(issues,'money_source_missing');end if;
   if finance_private.legacy_integrity_reference(_tenant,'employees',s->>'employee_id') is null or finance_private.legacy_integrity_reference(_tenant,'payroll_periods',s->>'payroll_period_id') is null then issues:=array_append(issues,'payroll_origin_not_in_tenant');end if;
  end if;
  if source_table='employee_advances' and s->>'payable_id' is not null and finance_private.legacy_integrity_reference(_tenant,'payables',s->>'payable_id') is null then issues:=array_append(issues,'payable_not_in_tenant');end if;
  if source_table in ('receivable_payment_reversals','closing_report_payments','load_payments') and s->>'receivable_id' is not null then
   if finance_private.legacy_integrity_reference(_tenant,'receivables',s->>'receivable_id') is null then issues:=array_append(issues,'receivable_not_in_tenant');end if;
  end if;
  if source_table='receivable_payment_reversals' and parent is not null and parent->>'receivable_id' is distinct from s->>'receivable_id' then issues:=array_append(issues,'parent_reference_mismatch');end if;
  if source_table='payroll_entry_items' and parent is not null and (parent->>'employee_id' is distinct from s->>'employee_id' or parent->>'payroll_period_id' is distinct from s->>'payroll_period_id') then issues:=array_append(issues,'parent_reference_mismatch');end if;
  context:=context||jsonb_build_object('origin_ids',jsonb_strip_nulls(jsonb_build_object('receivable_id',s->'receivable_id','payable_id',s->'payable_id','employee_id',s->'employee_id','payroll_period_id',s->'payroll_period_id','source_table',s->'source_table','source_id',s->'source_id','import_id',s->'import_id')));
  bank_id:=s->>'bank_transaction_id';
  if bank_id is not null then
   bank:=finance_private.legacy_integrity_reference(_tenant,'bank_transactions',bank_id);
   context:=context||jsonb_build_object('bank_transaction_id',bank_id);
   if bank is null then issues:=array_append(issues,'bank_source_not_in_tenant');
   elsif bank->>'bank_account_id' is distinct from account_id::text or (bank->>'amount')::numeric is distinct from (s->>'amount')::numeric or ((bank->>'posted_at')::timestamptz at time zone 'America/Sao_Paulo')::date is distinct from d or bank->>'transaction_type' is distinct from (case direction when 'in' then 'credit' else 'debit' end) then issues:=array_append(issues,'bank_source_mismatch');end if;
  end if;
  if source_table='bank_transactions' then
   if s->>'import_id' is not null and finance_private.legacy_integrity_reference(_tenant,'bank_statement_imports',s->>'import_id') is null then issues:=array_append(issues,'import_not_in_tenant');end if;
   for ref in
    select p.amount,p.bank_account_id,(p.received_at at time zone 'America/Sao_Paulo')::date as source_day,'credit'::text kind from public.receivables_payments p where p.tenant_id=_tenant and p.bank_transaction_id=source_id
    union all select p.amount,p.bank_account_id,(p.paid_at at time zone 'America/Sao_Paulo')::date,'debit' from public.payables_payments p where p.tenant_id=_tenant and p.bank_transaction_id=source_id
    union all select p.amount,p.bank_account_id,p.payment_date,'credit' from public.load_payments p where p.tenant_id=_tenant and p.bank_transaction_id=source_id
    union all select p.amount,(select x.bank_account_id from public.receivables_payments x where x.tenant_id=_tenant and x.id=p.payment_id),(p.effective_at at time zone 'America/Sao_Paulo')::date,'debit' from public.receivable_payment_reversals p where p.tenant_id=_tenant and p.bank_transaction_id=source_id
   loop
    if ref.amount is distinct from (s->>'amount')::numeric or ref.bank_account_id is distinct from account_id or ref.source_day is distinct from d or ref.kind is distinct from s->>'transaction_type' then issues:=array_append(issues,'referencing_source_mismatch');exit;end if;
   end loop;
  end if;
  context:=context||jsonb_build_object('amount_status',case when not money then 'projection_not_independent_money' when amount_cents is null then 'invalid_or_unknown' else 'exact_declared_cents' end);
  if cardinality(issues)>0 then return next;end if;
 end loop;
end$function$

CREATE OR REPLACE FUNCTION finance_private.paid_projection_chain(_tenant uuid, _table text, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.employee_advances%rowtype;p public.payables%rowtype;e public.employees%rowtype;pi public.payroll_entry_items%rowtype;pe public.payroll_entries%rowtype;period public.payroll_periods%rowtype;
 leg record;m public.finance_movements%rowtype;settle public.driver_settlement_payments%rowtype;parent jsonb;fp jsonb:='[]';snap jsonb:='{}';issue text;total numeric:=0;n integer;used numeric;
begin
 if _table='employee_advances' then
 select * into a from public.employee_advances where tenant_id=_tenant and id=_id;
 select * into e from public.employees where tenant_id=_tenant and id=a.employee_id;
 snap:=jsonb_build_object('advance',to_jsonb(a),'employee',to_jsonb(e));
 if a.id is null then issue:='paid_projection_source_missing';
 elsif a.status is distinct from 'paid' then issue:='advance_not_paid';
 elsif e.id is null or a.driver_id is distinct from e.driver_id then issue:='paid_projection_employee_mismatch';
 elsif not coalesce(a.amount>0 and a.amount*100=trunc(a.amount*100) and a.amount*100<=99999999999999,false) then issue:='paid_projection_invalid_amount';end if;
 select count(*) into n from public.payables t where t.tenant_id=_tenant and (t.id=a.payable_id or t.source_table='employee_advances' and t.source_id=a.id or t.source_table='financial_obligations' and t.source_id=a.financial_obligation_id);
 select * into p from public.payables where tenant_id=_tenant and id=a.payable_id;
 if n<>1 or p.id is null or p.source_table is distinct from 'employee_advances' or p.source_id is distinct from a.id or p.amount is distinct from a.amount or p.driver_id is distinct from a.driver_id or p.status='cancelled' then issue:=coalesce(issue,'advance_title_chain_invalid');end if;
 if p.source_metadata ? 'employee_id' and p.source_metadata->>'employee_id' is distinct from a.employee_id::text then issue:=coalesce(issue,'paid_projection_metadata_mismatch');end if;
 if p.source_metadata ? 'driver_id' and p.source_metadata->>'driver_id' is distinct from a.driver_id::text then issue:=coalesce(issue,'paid_projection_metadata_mismatch');end if;
 snap:=snap||jsonb_build_object('titles',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.payables t where tenant_id=_tenant and (t.id=a.payable_id or t.source_table='employee_advances' and t.source_id=a.id or t.source_table='financial_obligations' and t.source_id=a.financial_obligation_id)),
 'payments',(select coalesce(jsonb_agg(to_jsonb(pp) order by pp.id),'[]') from public.payables_payments pp where pp.tenant_id=_tenant and pp.payable_id=p.id),
 'links',(select coalesce(jsonb_agg(jsonb_build_object('link',to_jsonb(l),'reversal',(select to_jsonb(r) from public.finance_payable_link_reversals r where r.tenant_id=l.tenant_id and r.link_id=l.id)) order by l.id),'[]') from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payable_id=p.id));
 for leg in select pp.*, (select count(*) from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payment_id=pp.id and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id)) link_count,
  (select to_jsonb(l) from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payment_id=pp.id and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id) order by l.id limit 1) link
 from finance_private.active_payable_payments pp where pp.tenant_id=_tenant and pp.payable_id=p.id order by pp.id loop
 total:=total+leg.amount;
 select * into m from public.finance_movements where tenant_id=_tenant and id=(leg.link->>'movement_id')::uuid;
 used:=case when m.id is not null then finance_private.movement_used_cents(_tenant,m.id) end;
 if not coalesce(leg.link_count=1 and leg.amount>0 and leg.amount*100=trunc(leg.amount*100) and leg.amount*100<=99999999999999 and (leg.link->>'amount_cents')::numeric=leg.amount*100 and leg.link->>'payable_id'=p.id::text
 and m.id is not null and m.direction='out' and m.nature<>'transfer' and m.driver_id is not distinct from a.driver_id and m.bank_account_id=leg.bank_account_id and isfinite(leg.paid_at) and m.occurred_on=(leg.paid_at at time zone 'America/Sao_Paulo')::date and used>=leg.amount*100 and used<=m.amount_cents and exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=m.bank_account_id),false) then issue:=coalesce(issue,'advance_payment_chain_invalid');end if;
 if m.id is not null then fp:=fp||jsonb_build_array(jsonb_build_object('payment_id',leg.id,'link_id',leg.link->>'id','movement_id',m.id,'account_id',m.bank_account_id,'occurred_on',case when isfinite(m.occurred_on) then m.occurred_on end,'amount_cents',case when leg.amount*100=trunc(leg.amount*100) then trunc(leg.amount*100)::text end));end if;
 end loop;
 if total is distinct from a.amount or jsonb_array_length(fp)=0 then issue:=coalesce(issue,'advance_not_fully_paid');end if;
 elsif _table='payroll_entry_items' then
 select * into pi from public.payroll_entry_items where tenant_id=_tenant and id=_id;
 select * into pe from public.payroll_entries where tenant_id=_tenant and id=pi.payroll_entry_id;
 select * into period from public.payroll_periods where tenant_id=_tenant and id=pi.payroll_period_id;
 select * into e from public.employees where tenant_id=_tenant and id=pi.employee_id;
 snap:=jsonb_build_object('item',to_jsonb(pi),'entry',to_jsonb(pe),'period',to_jsonb(period),'employee',to_jsonb(e));
 if pi.id is null or pi.nature is distinct from 'already_paid' then issue:='paid_projection_source_missing';
 elsif pe.id is null or period.id is null or e.id is null or pe.payroll_period_id<>pi.payroll_period_id or pe.employee_id<>pi.employee_id or pe.driver_id is distinct from e.driver_id or pi.driver_id is distinct from e.driver_id then issue:='paid_projection_parent_mismatch';
 elsif pe.status='cancelled' or period.status='cancelled' then issue:='paid_projection_cancelled_requires_review';end if;
 if (select count(*) from public.payroll_entry_items x where x.tenant_id=_tenant and x.nature='already_paid' and x.employee_id=pi.employee_id and x.source_table=pi.source_table and x.source_id=pi.source_id)<>1 then issue:=coalesce(issue,'paid_projection_duplicate_source');end if;
 if pi.source_table='employee_advances' then
 parent:=finance_private.paid_projection_chain(_tenant,'employee_advances',pi.source_id);
 select * into a from public.employee_advances where tenant_id=_tenant and id=pi.source_id;
 if a.employee_id is distinct from pi.employee_id or a.driver_id is distinct from pi.driver_id or pi.amount is distinct from a.amount then issue:=coalesce(issue,'paid_projection_source_mismatch');end if;
 elsif pi.source_table='driver_settlement_payments' then
 parent:=finance_private.legacy_cut_settlement_evidence(_tenant,pi.source_id);
 select * into settle from public.driver_settlement_payments where tenant_id=_tenant and id=pi.source_id;
 select * into m from public.finance_movements where tenant_id=_tenant and id=(parent->'movement_ids'->>0)::uuid;
 if pi.amount is distinct from settle.amount or m.driver_id is distinct from pi.driver_id or pi.driver_id is null then issue:=coalesce(issue,'paid_projection_source_mismatch');end if;
 parent:=parent||jsonb_build_object('footprints',case when m.id is not null then jsonb_build_array(jsonb_build_object('payment_id',settle.id,'link_id',parent->>'link_id','movement_id',m.id,'account_id',m.bank_account_id,'occurred_on',m.occurred_on,'amount_cents',trunc(settle.amount*100)::text)) else '[]'::jsonb end,'snapshot',jsonb_build_object('payment',to_jsonb(settle),'movement',to_jsonb(m)));
 if pi.source_metadata ? 'movement_id' and pi.source_metadata->>'movement_id' is distinct from m.id::text then issue:=coalesce(issue,'paid_projection_metadata_mismatch');end if;
 if pi.source_metadata ? 'settlement_id' and pi.source_metadata->>'settlement_id' is distinct from settle.settlement_id::text then issue:=coalesce(issue,'paid_projection_metadata_mismatch');end if;
 else issue:=coalesce(issue,'paid_projection_unsupported_source');end if;
 if parent->'valid' is distinct from 'true'::jsonb then issue:=coalesce(issue,'paid_projection_parent_unresolved');end if;
 fp:=coalesce(parent->'footprints','[]');snap:=snap||jsonb_build_object('parent',parent);
 else issue:='paid_projection_unsupported_source';end if;
 snap:=snap||jsonb_build_object('footprints',fp,'movement_evidence',(select coalesce(jsonb_agg(to_jsonb(money_row) order by money_row.id),'[]') from public.finance_movements money_row where money_row.tenant_id=_tenant and exists(select 1 from jsonb_array_elements(fp) f where f->>'movement_id'=money_row.id::text)),
 'capacity_payable_links',(select coalesce(jsonb_agg(jsonb_build_object('link',to_jsonb(link_row),'reversal',(select to_jsonb(rv) from public.finance_payable_link_reversals rv where rv.tenant_id=_tenant and rv.link_id=link_row.id)) order by link_row.id),'[]') from public.finance_payable_movement_links link_row where link_row.tenant_id=_tenant and exists(select 1 from jsonb_array_elements(fp) f where f->>'movement_id'=link_row.movement_id::text)),
 'capacity_settlement_links',(select coalesce(jsonb_agg(jsonb_build_object('link',to_jsonb(link_row),'reversal',(select to_jsonb(rv) from public.finance_settlement_link_reversals rv where rv.tenant_id=_tenant and rv.link_id=link_row.id),'settlement',(select to_jsonb(st) from public.driver_settlements st where st.tenant_id=_tenant and st.id=link_row.settlement_id)) order by link_row.id),'[]') from public.finance_settlement_movement_links link_row where link_row.tenant_id=_tenant and exists(select 1 from jsonb_array_elements(fp) f where f->>'movement_id'=link_row.movement_id::text)),
 'capacity_expenses',(select coalesce(jsonb_agg(to_jsonb(allocation_row) order by allocation_row.id),'[]') from public.finance_expense_allocations allocation_row where allocation_row.tenant_id=_tenant and exists(select 1 from jsonb_array_elements(fp) f where f->>'movement_id'=allocation_row.movement_id::text)),
 'accounts',(select coalesce(jsonb_agg(to_jsonb(account_row) order by account_row.id),'[]') from public.bank_accounts account_row where account_row.tenant_id=_tenant and exists(select 1 from jsonb_array_elements(fp) f where f->>'account_id'=account_row.id::text)),
 'duplicate_items',(select coalesce(jsonb_agg(to_jsonb(other_item) order by other_item.id),'[]') from public.payroll_entry_items other_item where other_item.tenant_id=_tenant and other_item.employee_id=pi.employee_id and other_item.nature='already_paid' and other_item.source_table=pi.source_table and other_item.source_id=pi.source_id));
 return jsonb_build_object('version',1,'valid',issue is null,'issue',issue,'source_table',_table,'source_id',_id,'footprints',fp,'snapshot',snap,'revision',md5(snap::text));
end$function$

CREATE OR REPLACE FUNCTION finance_private.process_automatic_reconciliation(_verification uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job public.finance_automatic_reconciliation_jobs%rowtype;assessment jsonb;e public.finance_bank_entries%rowtype;
 m public.finance_movements%rowtype;snapshot jsonb;actor_name text;group_id uuid;processed integer:=0;matched integer:=0;account uuid;
begin
 select * into job from public.finance_automatic_reconciliation_jobs where verification_id=_verification;
 if not found or job.status<>'pending' then return 0;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(job.tenant_id::text||':finance',0)) then return 0;end if;
 select * into job from public.finance_automatic_reconciliation_jobs where verification_id=_verification and status='pending' for update skip locked;
 if not found then return 0;end if;
 if (select id from public.finance_statement_verifications where tenant_id=job.tenant_id and import_id=job.import_id order by created_at desc,id desc limit 1) is distinct from _verification then
  update public.finance_automatic_reconciliation_jobs set status='superseded',issue='newer_source_verification',updated_at=clock_timestamp() where verification_id=_verification;return 0;end if;
 if not exists(select 1 from public.tenant_memberships where tenant_id=job.tenant_id and user_id=job.actor_id and active and role::text in('owner','admin','operator'))
  or exists(select 1 from public.tenant_memberships where tenant_id=job.tenant_id and user_id=job.actor_id and active and role::text='driver')
  or exists(select 1 from public.drivers where tenant_id=job.tenant_id and user_id=job.actor_id and active) then
  update public.finance_automatic_reconciliation_jobs set status='review',issue='initiator_access_changed',updated_at=clock_timestamp() where verification_id=_verification;return 0;end if;
 select bank_account_id into account from public.finance_statement_imports where tenant_id=job.tenant_id and id=job.import_id;
 perform 1 from public.bank_accounts where tenant_id=job.tenant_id and id=account for share;
 assessment:=finance_private.native_statement_account(job.tenant_id,job.import_id);
 if assessment->>'status'<>'matched_exact' then
  update public.finance_automatic_reconciliation_jobs set status='review',issue='native_account_'||(assessment->>'status'),updated_at=clock_timestamp() where verification_id=_verification;return 0;end if;
 select coalesce(raw_user_meta_data->>'full_name',email,job.actor_id::text) into actor_name from auth.users where id=job.actor_id;
 for e in select be.* from public.finance_bank_entries be where be.tenant_id=job.tenant_id and be.bank_account_id=account
  and (job.cursor_id is null or be.id>job.cursor_id)
  and exists(select 1 from public.finance_statement_rows sr where sr.tenant_id=job.tenant_id and sr.import_id=job.import_id and sr.bank_entry_id=be.id)
  order by be.id limit 100
 loop
  processed:=processed+1;job.cursor_id:=e.id;
  if e.bank_id is null or not finance_private.bank_entry_active(job.tenant_id,e.id)
   or not finance_private.automatic_bank_reference_uncontested(job.tenant_id,e.id)
   or exists(select 1 from public.finance_statement_identity_reviews where tenant_id=job.tenant_id and bank_entry_id=e.id)
   or exists(select 1 from public.finance_reconciliation_groups g where g.tenant_id=job.tenant_id and g.bank_entry_ids@>array[e.id]) then continue;end if;
  if (finance_private.native_statement_account(job.tenant_id,e.first_import_id)->>'status')<>'matched_exact' then continue;end if;
  select * into m from public.finance_movements where tenant_id=job.tenant_id and bank_account_id=account and bank_reference=e.bank_id order by id limit 1;
  if not found then continue;end if;
  if exists(select 1 from public.finance_movements other where other.tenant_id=job.tenant_id and other.bank_account_id=account and other.bank_reference=e.bank_id and other.id<>m.id)
   or m.amount_cents<>abs(e.amount_cents) or m.occurred_on<>e.posted_on or (m.direction='in')<>(e.amount_cents>0)
   or exists(select 1 from public.finance_reconciliation_groups g where g.tenant_id=job.tenant_id and g.movement_ids@>array[m.id]) then continue;end if;
  snapshot:=finance_private.reconciliation_snapshot_internal(job.tenant_id,array[m.id],array[e.id])||jsonb_build_object('automatic_rule','native_reference_exact_v1','native_account_assessment',assessment);
  group_id:=gen_random_uuid();
  insert into public.finance_reconciliation_groups(id,tenant_id,bank_account_id,direction,amount_cents,movement_ids,bank_entry_ids,method,actor_id,actor_name,reason,account_evidence,evidence_snapshot)
  values(group_id,job.tenant_id,account,m.direction,m.amount_cents,array[m.id],array[e.id],'automatic_reference',job.actor_id,coalesce(actor_name,job.actor_id::text),
   'Referência única, data, valor e sentido idênticos na conta nativa conferida','Banco, agência, conta e tipo correspondem a um cadastro único',snapshot);
  insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
  values(job.tenant_id,'reconciliation_group',group_id,'bank_reconciled_automatically',job.actor_id,coalesce(actor_name,job.actor_id::text),
   'Conciliação automática por referência única, data, valor, sentido e conta nativa',jsonb_build_object('group_id',group_id,'method','automatic_reference','rule','native_reference_exact_v1','verification_id',_verification,'manual',false));
  matched:=matched+1;
 end loop;
 update public.finance_automatic_reconciliation_jobs set cursor_id=job.cursor_id,matched_count=matched_count+matched,
  status=case when processed<100 then 'complete' else 'pending' end,issue=null,updated_at=clock_timestamp() where verification_id=_verification;
 return matched;
end;$function$

CREATE OR REPLACE FUNCTION finance_private.reconciliation_evidence_issue(_tenant uuid, _group uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare g public.finance_reconciliation_groups%rowtype;account_snapshot jsonb;current_account jsonb;
begin
 select * into g from public.finance_reconciliation_groups where tenant_id=_tenant and id=_group;
 if not found then return 'group_unavailable';end if;
 if (select count(*) from public.finance_bank_entries where tenant_id=_tenant and id=any(g.bank_entry_ids))<>cardinality(g.bank_entry_ids)
  or exists(select 1 from unnest(g.bank_entry_ids) id where not finance_private.bank_entry_active(_tenant,id)) then return 'bank_identity_inactive';end if;
 if exists(select 1 from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=any(g.bank_entry_ids)
  and (select v.outcome from public.finance_statement_verifications v where v.tenant_id=_tenant and v.import_id=e.first_import_id order by v.created_at desc,v.id desc limit 1) is distinct from 'rows_match') then
  return 'source_changed';end if;
 select value into account_snapshot from jsonb_array_elements(g.evidence_snapshot->'accounts') where value->>'id'=g.bank_account_id::text;
 select jsonb_build_object('id',a.id,'bank_code',to_jsonb(a)->'bank_code','branch_number',to_jsonb(a)->'branch_number',
  'account_number',to_jsonb(a)->'account_number','account_type',to_jsonb(a)->'account_type') into current_account
 from public.bank_accounts a where a.tenant_id=_tenant and a.id=g.bank_account_id;
 if current_account is null or account_snapshot is null or current_account is distinct from (account_snapshot-'name'-'bank_name') then return 'account_changed';end if;

 if g.method='automatic_reference' then
  if exists(select 1 from unnest(g.bank_entry_ids) entry_id where not finance_private.automatic_bank_reference_uncontested(_tenant,entry_id)) then return 'automatic_bank_reference_contested';end if;
  if exists(select 1 from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=any(g.bank_entry_ids)
   and (finance_private.native_statement_account(_tenant,e.first_import_id)->>'status') is distinct from 'matched_exact') then return 'automatic_account_unconfirmed';end if;
  if cardinality(g.movement_ids)<>1 or cardinality(g.bank_entry_ids)<>1 then return 'automatic_reference_ambiguous';end if;
  if (select count(*) from public.finance_movements m join public.finance_bank_entries e
   on e.tenant_id=m.tenant_id and e.bank_account_id=m.bank_account_id and e.bank_id=m.bank_reference
   where e.tenant_id=_tenant and e.id=any(g.bank_entry_ids))<>1 then return 'automatic_reference_ambiguous';end if;
 end if;
 return null;

end;$function$

CREATE OR REPLACE FUNCTION finance_private.record_internal_transfer(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;actor uuid:=auth.uid();prior public.finance_commands%rowtype;
 source uuid;destination uuid;source_name text;destination_name text;cents bigint;debit_date date;credit_date date;
 debit uuid:=gen_random_uuid();credit uuid:=gen_random_uuid();transfer uuid:=gen_random_uuid();result jsonb;actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _payload->>'version' is distinct from '1' or _payload->>'both_recorded' is distinct from 'true'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','source_account_id','destination_account_id','amount_cents','debited_on','credited_on','source_reference','destination_reference','reason','both_recorded')) then
  raise exception 'finance_invalid_payload' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if prior.actor_id<>actor or prior.action<>'record_internal_transfer' or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;
  return prior.result;
 end if;
 if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'debited_on','') !~ '^\d{4}-\d{2}-\d{2}$'
 or coalesce(_payload->>'credited_on','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 cents:=(_payload->>'amount_cents')::bigint;debit_date:=(_payload->>'debited_on')::date;credit_date:=(_payload->>'credited_on')::date;
 if cents<=0 or credit_date<debit_date or credit_date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then raise exception 'finance_invalid_realized_movement' using errcode='22023';end if;
 source:=(_payload->>'source_account_id')::uuid;destination:=(_payload->>'destination_account_id')::uuid;
 if source is null or destination is null or source=destination then raise exception 'finance_transfer_distinct_accounts_required' using errcode='22023';end if;
 -- Lock both registrations in a stable order before checking tenant/activity.
 perform 1 from public.bank_accounts where tenant_id=t and id in(source,destination) order by id for share;
 select name into source_name from public.bank_accounts where id=source and tenant_id=t and active;
 if not found then raise exception 'finance_invalid_account' using errcode='22023';end if;
 select name into destination_name from public.bank_accounts where id=destination and tenant_id=t and active;
 if not found then raise exception 'finance_invalid_account' using errcode='22023';end if;
 if exists(select 1 from public.finance_movements m where m.tenant_id=t and
  ((m.bank_account_id=source and m.bank_reference=nullif(btrim(_payload->>'source_reference'),'')) or
   (m.bank_account_id=destination and m.bank_reference=nullif(btrim(_payload->>'destination_reference'),'')))) then
  raise exception 'finance_reference_already_recorded' using errcode='23505';end if;
 insert into public.finance_movements(id,tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,description,beneficiary_name,bank_reference,created_by)
 values(debit,t,source,'out','transfer',cents,debit_date,'Transferência entre contas próprias',left(coalesce(destination_name,destination::text),300),nullif(btrim(_payload->>'source_reference'),''),actor),
 (credit,t,destination,'in','transfer',cents,credit_date,'Transferência entre contas próprias',left(coalesce(source_name,source::text),300),nullif(btrim(_payload->>'destination_reference'),''),actor);
 insert into public.finance_internal_transfers(id,tenant_id,outgoing_id,incoming_id,created_by) values(transfer,t,debit,credit,actor);
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'transfer_id',transfer,'outgoing_id',debit,'incoming_id',credit,'confirmed',true,'bank_confirmed',false);
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(t,'internal_transfer',transfer,'internal_transfer_recorded',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),result||jsonb_build_object('amount_cents',cents,'source_account_id',source,'destination_account_id',destination,'debited_on',debit_date,'credited_on',credit_date));
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'record_internal_transfer',_payload,result);
 return result;
end$function$

CREATE OR REPLACE FUNCTION finance_private.record_movement(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 t uuid; actor uuid:=auth.uid(); request uuid; existing public.finance_commands%rowtype;
 movement uuid; account uuid; driver uuid; cents bigint; result jsonb; actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 t:=(_payload->>'tenant_id')::uuid; request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501'; end if;
 if request is null or _payload->>'version' is distinct from '1'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in
 ('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
  'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason')) then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 -- Serializes retries and reference checks, including requests with different IDs.
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'record_movement' or existing.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 if _payload->>'nature'='transfer' then raise exception 'finance_transfer_pair_required' using errcode='22023';end if;
 if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 cents:=(_payload->>'amount_cents')::bigint;
 if cents<=0 or (_payload->>'occurred_on')::date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then
  raise exception 'finance_invalid_realized_movement' using errcode='22023'; end if;
 account:=(_payload->>'bank_account_id')::uuid; driver:=nullif(_payload->>'driver_id','')::uuid;
 perform 1 from public.bank_accounts where id=account and tenant_id=t and active for share;
 if not found then raise exception 'finance_invalid_account' using errcode='22023'; end if;
 if driver is not null then
  perform 1 from public.drivers where id=driver and tenant_id=t and active for share;
  if not found then raise exception 'finance_invalid_driver' using errcode='22023'; end if;
 end if;
 if _payload->>'nature'='driver_advance' and (driver is null or _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_driver_advance' using errcode='22023'; end if;
 if (_payload->>'nature' in ('receipt','customer_advance') and _payload->>'direction' is distinct from 'in')
 or (_payload->>'nature'='payment' and _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_direction' using errcode='22023';end if;
 if nullif(btrim(_payload->>'receipt_path'),'') is not null and
  ((_payload->>'receipt_path') not like t::text||'/%' or (_payload->>'receipt_path') like '%..%') then
  raise exception 'finance_invalid_receipt_scope' using errcode='22023'; end if;
 if nullif(btrim(_payload->>'bank_reference'),'') is not null and exists(
  select 1 from public.finance_movements where tenant_id=t and bank_account_id=account
   and bank_reference=btrim(_payload->>'bank_reference')) then
  raise exception 'finance_reference_already_recorded' using errcode='23505'; end if;
 insert into public.finance_movements(tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,
  description,beneficiary_name,beneficiary_document,driver_id,bank_reference,receipt_path,created_by)
 values(t,account,_payload->>'direction',_payload->>'nature',cents,(_payload->>'occurred_on')::date,
  btrim(_payload->>'description'),btrim(_payload->>'beneficiary_name'),nullif(btrim(_payload->>'beneficiary_document'),''),
  driver,nullif(btrim(_payload->>'bank_reference'),''),nullif(btrim(_payload->>'receipt_path'),''),actor)
 returning id into movement;
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 select t,'movement',movement,'recorded',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),to_jsonb(m)
 from public.finance_movements m where m.id=movement;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'movement_id',movement,'confirmed',true);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result)
 values(t,request,actor,'record_movement',_payload,result);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.record_transfer_stage(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;actor uuid:=auth.uid();stage text;prior public.finance_commands%rowtype;
 source uuid;destination uuid;party text;cents bigint;day date;movement uuid:=gen_random_uuid();departure uuid;pair uuid;
 original public.finance_movements%rowtype;pending public.finance_transfer_departures%rowtype;result jsonb;actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;stage:=_payload->>'stage';
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _payload->>'version' is distinct from '1' or stage is null or stage not in('depart','arrive') or _payload->>'occurred' is distinct from 'true'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','stage','source_account_id','destination_account_id','amount_cents','occurred_on','bank_reference','reason','occurred','departure_id')) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if (stage='arrive' and (_payload ? 'source_account_id' or _payload ? 'destination_account_id' or _payload ? 'amount_cents'))
 or (stage='depart' and _payload ? 'departure_id') then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if prior.actor_id<>actor or prior.action<>'record_transfer_stage' or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;
  return prior.result;
 end if;
 if length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000 or coalesce(_payload->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 day:=(_payload->>'occurred_on')::date;
 if day>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then raise exception 'finance_invalid_realized_movement' using errcode='22023';end if;
 if stage='depart' then
  if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
  cents:=(_payload->>'amount_cents')::bigint;source:=(_payload->>'source_account_id')::uuid;destination:=(_payload->>'destination_account_id')::uuid;
  if cents<=0 or source is null or destination is null or source=destination then raise exception 'finance_invalid_payload' using errcode='22023';end if;
  perform 1 from public.bank_accounts where tenant_id=t and id in(source,destination) order by id for share;
  if (select count(*) from public.bank_accounts where tenant_id=t and active and id in(source,destination))<>2 then raise exception 'finance_invalid_account' using errcode='22023';end if;
  select name into party from public.bank_accounts where id=destination;
 else
  departure:=(_payload->>'departure_id')::uuid;
  select * into pending from public.finance_transfer_departures where tenant_id=t and id=departure;
  if not found then raise exception 'finance_transfer_departure_not_found' using errcode='P0002';end if;
  if exists(select 1 from public.finance_internal_transfers where tenant_id=t and outgoing_id=pending.outgoing_id) then raise exception 'finance_transfer_already_arrived' using errcode='23514';end if;
  select * into original from public.finance_movements where tenant_id=t and id=pending.outgoing_id;
  if not found or original.direction<>'out' or original.nature<>'transfer' or day<original.occurred_on then raise exception 'finance_transfer_invalid_arrival' using errcode='23514';end if;
  cents:=original.amount_cents;source:=original.bank_account_id;destination:=pending.destination_account_id;
  perform 1 from public.bank_accounts where tenant_id=t and id=destination and active for share;
  if not found then raise exception 'finance_invalid_account' using errcode='22023';end if;
  select name into party from public.bank_accounts where tenant_id=t and id=source;
 end if;
 if exists(select 1 from public.finance_movements where tenant_id=t and bank_account_id=case when stage='depart' then source else destination end
  and bank_reference=nullif(btrim(_payload->>'bank_reference'),'')) then raise exception 'finance_reference_already_recorded' using errcode='23505';end if;
 insert into public.finance_movements(id,tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,description,beneficiary_name,bank_reference,created_by)
 values(movement,t,case when stage='depart' then source else destination end,case when stage='depart' then 'out' else 'in' end,'transfer',cents,day,
  case when stage='depart' then 'Saída de transferência em trânsito' else 'Entrada de transferência anteriormente em trânsito' end,left(coalesce(party,'Conta própria'),300),nullif(btrim(_payload->>'bank_reference'),''),actor);
 if stage='depart' then
  departure:=gen_random_uuid();insert into public.finance_transfer_departures(id,tenant_id,outgoing_id,destination_account_id,created_by) values(departure,t,movement,destination,actor);
 else
  pair:=gen_random_uuid();insert into public.finance_internal_transfers(id,tenant_id,outgoing_id,incoming_id,created_by) values(pair,t,pending.outgoing_id,movement,actor);
 end if;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'stage',stage,'departure_id',departure,'movement_id',movement,'transfer_id',pair,'confirmed',true,'bank_confirmed',false);
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(t,'transfer_departure',departure,case when stage='depart' then 'transfer_departed' else 'transfer_arrived' end,actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),result||jsonb_build_object('amount_cents',cents,'source_account_id',source,'destination_account_id',destination,'occurred_on',day));
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'record_transfer_stage',_payload,result);
 return result;
end$function$

