CREATE OR REPLACE FUNCTION finance_private.expense_cancellation_context(_tenant uuid, _expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.finance_expense_items%rowtype;b public.finance_expense_batches%rowtype;p public.payables%rowtype;cancel public.finance_expense_cancellations%rowtype;snapshot jsonb;issue text;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into e from public.finance_expense_items where tenant_id=_tenant and id=_expense;select * into b from public.finance_expense_batches where tenant_id=_tenant and id=e.batch_id;select * into p from public.payables where tenant_id=_tenant and id=e.payable_id;
 select * into cancel from public.finance_expense_cancellations where tenant_id=_tenant and expense_id=_expense;
 snapshot:=jsonb_build_object('expense',to_jsonb(e),'batch',to_jsonb(b),'payable',to_jsonb(p),'supplier',(select to_jsonb(s) from public.clients s where s.tenant_id=_tenant and s.id=e.supplier_id),'cancellation',case when cancel.id is null then null else to_jsonb(cancel)-'source_snapshot' end,
 'origin_items',(select coalesce(jsonb_agg(jsonb_build_object('request_id',c.request_id,'item',item) order by c.request_id),'[]') from public.finance_commands c cross join lateral jsonb_array_elements(c.payload->'items') item where c.tenant_id=_tenant and c.action='record_expense_batch' and c.result->>'batch_id'=b.id::text and item->>'id'=e.id::text),
 'driver',(select to_jsonb(d) from public.drivers d where d.tenant_id=_tenant and d.id=b.driver_id),
 'source_payables',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payables x where x.tenant_id=_tenant and x.source_table='finance_expense_items' and x.source_id=e.id),
 'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payables_payments x where x.tenant_id=_tenant and x.payable_id=e.payable_id),
 'allocations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_expense_allocations x where x.tenant_id=_tenant and x.expense_id=e.id),
 'payable_links',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_payable_movement_links x where x.tenant_id=_tenant and x.payable_id=e.payable_id),
 'legacy_links',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_legacy_expense_cost_links x where x.tenant_id=_tenant and x.cost_id=e.id),
 'maintenance_claims',(select coalesce(jsonb_agg(to_jsonb(x) order by x.cost_id),'[]') from public.finance_maintenance_cost_claims x where x.tenant_id=_tenant and x.cost_id=e.id),
 'labor_history',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_maintenance_labor_links x where x.tenant_id=_tenant and x.cost_id=e.id),
 'part_history',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_maintenance_direct_part_links x where x.tenant_id=_tenant and x.cost_id=e.id),
 'stock_history',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_stock_acquisition_links x where x.tenant_id=_tenant and x.cost_id=e.id),
 'settlements',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.driver_settlements x where x.tenant_id=_tenant and x.dispatch_trip_id=b.trip_id),
 'advances',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.employee_advances x where x.tenant_id=_tenant and x.payable_id=e.payable_id),
 'payroll_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payroll_entry_items x where x.tenant_id=_tenant and (x.source_table='finance_expense_items' and x.source_id=e.id or x.source_table='payables' and x.source_id=e.payable_id)),
 'obligations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.financial_obligations x where x.tenant_id=_tenant and x.source_table='finance_expense_items' and x.source_id=e.id),
 'closure_dependencies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.closure_id,x.source_kind,x.source_id),'[]') from public.finance_account_period_dependencies x where x.tenant_id=_tenant and ((x.source_kind='finance_expense_items' and x.source_id=e.id) or(x.source_kind='payables' and x.source_id=e.payable_id))));
 if e.id is null or b.id is null then issue:='finance_expense_not_found';
 elsif cancel.id is not null then issue:='finance_expense_already_cancelled';
 elsif e.unloading_id is not null or e.category='unloading' then issue:='finance_expense_unloading_requires_resolution';
 elsif jsonb_array_length(snapshot->'payments')>0 or jsonb_array_length(snapshot->'allocations')>0 or jsonb_array_length(snapshot->'payable_links')>0 then issue:='finance_expense_money_dependency';
 elsif jsonb_array_length(snapshot->'source_payables')<>1 or e.payable_id is null or p.id is null or p.source_table is distinct from 'finance_expense_items' or p.source_id is distinct from e.id or p.amount*100 is distinct from e.amount_cents::numeric or p.status not in('pending','approved') or p.driver_id is distinct from b.driver_id or jsonb_array_length(snapshot->'origin_items')<>1 or (case snapshot#>>'{origin_items,0,item,payee_type}' when 'supplier' then p.supplier_id is distinct from e.supplier_id or (e.supplier_id is null and p.supplier_name is distinct from e.supplier_name) when 'driver' then b.driver_id is null or p.supplier_id is not null or p.supplier_name is distinct from snapshot#>>'{driver,name}' else true end) then issue:='finance_expense_payable_inconsistent';
 elsif jsonb_array_length(snapshot->'legacy_links')+jsonb_array_length(snapshot->'maintenance_claims')+jsonb_array_length(snapshot->'labor_history')+jsonb_array_length(snapshot->'part_history')+jsonb_array_length(snapshot->'stock_history')>0 then issue:='finance_expense_source_association_dependency';
 elsif jsonb_array_length(snapshot->'advances')>0 or jsonb_array_length(snapshot->'payroll_items')>0 or exists(select 1 from public.driver_settlements x where x.tenant_id=_tenant and x.dispatch_trip_id=b.trip_id and x.status not in('pending_review','in_review','reopened')) then issue:='finance_expense_protected_composition';
 elsif jsonb_array_length(snapshot->'obligations')>0 then issue:='finance_expense_obligation_dependency';
 elsif exists(select 1 from public.finance_account_period_dependencies d join public.finance_account_period_closures c on c.tenant_id=d.tenant_id and c.id=d.closure_id where d.tenant_id=_tenant and ((d.source_kind='finance_expense_items' and d.source_id=e.id) or(d.source_kind='payables' and d.source_id=e.payable_id)) and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=_tenant and r.closure_id=c.id)) then issue:='finance_expense_closed_period_dependency';end if;
 if issue is null then begin perform finance_private.assert_closed_source_mutable(_tenant,'finance_expense_items',to_jsonb(e));perform finance_private.assert_closed_source_mutable(_tenant,'payables',to_jsonb(p));exception when sqlstate '55000' then issue:='finance_expense_closed_period_dependency';end;end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'expense_id',_expense,'revision',md5(snapshot::text),'eligible',issue is null,'issue',issue,'snapshot',snapshot,'cancellation',case when cancel.id is null then null else to_jsonb(cancel)-'source_snapshot' end,'effects',jsonb_build_object('cost_removed_cents',case when e.id is not null then e.amount_cents::text end,'obligation_cancelled_cents',case when p.id is not null then trunc(p.amount*100)::text end,'cash_changed',false));
end$function$

CREATE OR REPLACE FUNCTION finance_private.manual_expense_cancellation_context(_tenant uuid, _payable uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;cmd public.finance_commands%rowtype;cancel public.finance_manual_expense_cancellations%rowtype;snapshot jsonb;issue text;cents numeric;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into p from public.payables where tenant_id=_tenant and id=_payable;
 select * into cmd from public.finance_commands where tenant_id=_tenant and action='record_manual_expense' and result->>'payable_id'=_payable::text order by request_id limit 1;
 select * into cancel from public.finance_manual_expense_cancellations where tenant_id=_tenant and payable_id=_payable;
 snapshot:=jsonb_build_object('payable',to_jsonb(p),'command',to_jsonb(cmd),'supplier',(select to_jsonb(s) from public.clients s where s.tenant_id=_tenant and s.id=p.supplier_id),
 'commands',(select coalesce(jsonb_agg(to_jsonb(c) order by c.request_id),'[]') from public.finance_commands c where c.tenant_id=_tenant and c.action='record_manual_expense' and c.result->>'payable_id'=_payable::text),
 'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payables_payments x where x.tenant_id=_tenant and x.payable_id=_payable),
 'links',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_payable_movement_links x where x.tenant_id=_tenant and x.payable_id=_payable),
 'evidence',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_manual_expense_evidence x where x.tenant_id=_tenant and x.payable_id=_payable),
 'expense_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_expense_items x where x.tenant_id=_tenant and x.payable_id=_payable),
 'advances',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.employee_advances x where x.tenant_id=_tenant and x.payable_id=_payable),
 'payroll_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payroll_entry_items x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'settlement_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.driver_settlement_items x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'obligations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.financial_obligations x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'closure_dependencies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.closure_id,x.source_kind,x.source_id),'[]') from public.finance_account_period_dependencies x where x.tenant_id=_tenant and (x.source_kind='payables' and x.source_id=_payable or x.source_kind in('manual_expense','finance_commands') and x.source_id=cmd.request_id)),
 'cancellation',case when cancel.id is not null then to_jsonb(cancel)-'source_snapshot' end);
 if coalesce(cmd.payload->>'amount_cents','') ~ '^[0-9]{1,14}$' then cents:=(cmd.payload->>'amount_cents')::numeric;end if;
 if p.id is null or cmd.request_id is null then issue:='finance_manual_expense_not_found';
 elsif cancel.id is not null then issue:='finance_manual_expense_already_cancelled';
 elsif jsonb_array_length(snapshot->'commands')<>1 or cents is null or cents<=0 or cents>99999999999999
  or cmd.payload->>'request_id' is distinct from cmd.request_id::text or cmd.result->>'request_id' is distinct from cmd.request_id::text or cmd.payload->'version' is distinct from '1'::jsonb or cmd.result->'confirmed' is distinct from 'true'::jsonb or cmd.payload->>'tenant_id' is distinct from _tenant::text or cmd.result->>'tenant_id' is distinct from _tenant::text
  or p.amount*100 is distinct from cents or p.status not in('pending','approved') or p.paid_amount is distinct from 0::numeric or p.paid_at is not null
  or p.source is distinct from 'manual' or p.source_table is not null or p.source_id is not null or p.driver_id is not null or p.dispatch_trip_id is not null or p.load_id is not null or p.vehicle_id is not null
  or p.supplier_id::text is distinct from nullif(cmd.payload->>'supplier_id','') or p.supplier_name is distinct from btrim(cmd.payload->>'supplier_name')
  or (p.competence_date is not null and not isfinite(p.competence_date)) or (p.due_date is not null and not isfinite(p.due_date)) or p.category is distinct from cmd.payload->>'category' or p.competence_date::text is distinct from nullif(cmd.payload->>'competence_date','') or p.due_date::text is distinct from nullif(cmd.payload->>'due_date','') then issue:='finance_manual_expense_source_inconsistent';
 elsif p.category='unloading' then issue:='finance_manual_expense_unloading_requires_resolution';
 elsif jsonb_array_length(snapshot->'payments')+jsonb_array_length(snapshot->'links')>0 or nullif(cmd.payload->>'movement_id','') is not null or nullif(cmd.result->>'movement_id','') is not null or cmd.result->'allocation' is distinct from 'null'::jsonb then issue:='finance_manual_expense_money_dependency';
 elsif jsonb_array_length(snapshot->'expense_items')+jsonb_array_length(snapshot->'advances')+jsonb_array_length(snapshot->'payroll_items')+jsonb_array_length(snapshot->'settlement_items')+jsonb_array_length(snapshot->'obligations')>0 then issue:='finance_manual_expense_materialization_dependency';
 end if;
 if issue is null then begin perform finance_private.assert_closed_source_mutable(_tenant,'payables',to_jsonb(p));exception when sqlstate '55000' then issue:='finance_manual_expense_closed_period_dependency';end;end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'original_request_id',cmd.request_id,'revision',md5(snapshot::text),'eligible',issue is null,'issue',issue,'snapshot',snapshot,'cancellation',case when cancel.id is not null then to_jsonb(cancel)-'source_snapshot' end,'effects',jsonb_build_object('cost_removed_cents',cents::text,'obligation_cancelled_cents',cents::text,'cash_changed',false));
end$function$

functions.definition:
CREATE OR REPLACE FUNCTION finance_private.assert_closed_source_mutable(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid;start_date date;end_date date;ref record;source_table text;source jsonb;identifier uuid;raw_date text;hit boolean:=false;outgoing public.finance_movements%rowtype;incoming public.finance_movements%rowtype;native jsonb;imp public.finance_statement_imports%rowtype;registered public.bank_accounts%rowtype;closed public.finance_account_period_closures%rowtype;anchor date;
begin
 if _row is null or _row='null'::jsonb then return;end if;
 if _table='employee_advances' and _row->>'status' is distinct from 'paid' and _row->>'paid_at' is null then return;end if;
 if _depth>8 then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
 if not finance_private.closed_interval_exists(_tenant,null,null,null) then return;end if;
 identifier:=nullif(_row->>'id','')::uuid;
 if exists(select 1 from public.finance_account_period_dependencies d join public.finance_account_period_closures c on c.tenant_id=d.tenant_id and c.id=d.closure_id where d.tenant_id=_tenant and d.source_kind=_table and d.source_id=identifier and d.dependency_role<>'composition_snapshot' and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
 account:=coalesce(nullif(_row->>'bank_account_id','')::uuid,nullif(_row->>'account_id','')::uuid);
 if _table='finance_internal_transfers' then
  select * into outgoing from public.finance_movements where tenant_id=_tenant and id=(_row->>'outgoing_id')::uuid;
  select * into incoming from public.finance_movements where tenant_id=_tenant and id=(_row->>'incoming_id')::uuid;
  -- An already identified departure may arrive later. Its frozen leg stays intact.
  if finance_private.closed_interval_exists(_tenant,outgoing.bank_account_id,outgoing.occurred_on,outgoing.occurred_on) then
   if not exists(select 1 from public.finance_transfer_departures p where p.tenant_id=_tenant and p.outgoing_id=outgoing.id and p.destination_account_id=incoming.bank_account_id
    and not exists(select 1 from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=outgoing.bank_account_id and outgoing.occurred_on between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)
      and (incoming.occurred_on<=c.period_end or not exists(select 1 from public.finance_account_period_dependencies d where d.tenant_id=_tenant and d.closure_id=c.id and d.source_kind='finance_transfer_departures' and d.source_id=p.id)))) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',to_jsonb(incoming),_depth+1);return;
  end if;
 end if;
 if _table='finance_statement_verifications' then
  select * into imp from public.finance_statement_imports where tenant_id=_tenant and id=(_row->>'import_id')::uuid;
  native:=_row#>'{report,native_evidence}';
  if native is not null then
   if finance_private.closed_interval_exists(_tenant,imp.bank_account_id,(native#>>'{period,start,date}')::date,(native#>>'{period,end,date}')::date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   anchor:=(native#>>'{ledger_balance,as_of,date}')::date;
   for closed in select c.* from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=imp.bank_account_id and anchor between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id) loop
    select * into registered from public.bank_accounts where tenant_id=_tenant and id=imp.bank_account_id;
    if anchor is distinct from closed.period_end or native#>>'{ledger_balance,amount_cents}' is distinct from closed.snapshot#>>'{balances,closing_cents}'
     or native#>>'{ledger_balance,as_of,offset_minutes}' is distinct from '-180' or native#>>'{period,start,offset_minutes}' is distinct from '-180' or native#>>'{period,end,offset_minutes}' is distinct from '-180'
     or native->>'currency' is distinct from 'BRL' or native->>'parser_version' is distinct from 'native-ofx-v1'
     or native#>>'{account,bank_id}' is distinct from btrim(registered.bank_code) or native#>>'{account,branch_id}' is distinct from btrim(registered.branch_number) or native#>>'{account,account_id}' is distinct from btrim(registered.account_number)
     or native#>>'{account,account_type}' is distinct from (case registered.account_type when 'checking' then 'CHECKING' when 'savings' then 'SAVINGS' end)
     or _row->>'outcome' is distinct from 'rows_match' or _row#>>'{report,hash_verified}' is distinct from 'true' or _row#>>'{report,actual_hash}' is distinct from imp.file_hash or _row#>>'{report,identity_trust}' is distinct from 'native_file_identifier'
     or native->>'outside_declared_period' is distinct from 'false' or native->'repeated_bank_ids' is distinct from '[]'::jsonb
    then raise exception 'finance_closed_anchor_conflict' using errcode='55000';end if;
   end loop;
  end if;
 end if;
 if _table in('finance_statement_imports','finance_statement_coverage_approvals','finance_period_evidence_reviews','finance_legacy_cut_reviews') then
  start_date:=(_row->>'period_start')::date;end_date:=(_row->>'period_end')::date;
 elsif _table='finance_account_openings' then start_date:=(_row->>'effective_from')::date;end_date:=null;
 else
  raw_date:=coalesce(_row->>'occurred_on',_row->>'posted_on',_row->>'posted_at',_row->>'received_at',_row->>'paid_at',_row->>'effective_at',_row->>'payment_date',_row->>'advance_date',_row->>'occurred_at',_row->>'competence_date');
  if raw_date is not null then start_date:=(raw_date::timestamptz at time zone 'America/Sao_Paulo')::date;
   if raw_date ~ '^\d{4}-\d{2}-\d{2}$' then start_date:=raw_date::date;end if;end_date:=start_date;end if;
 end if;
 if start_date is not null or _table in('finance_movements','finance_bank_entries','bank_transactions','receivables_payments','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items') then
  if finance_private.closed_interval_exists(_tenant,account,start_date,end_date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
  hit:=true;
 end if;
 for ref in select key,value from jsonb_each_text(_row) where key in('import_id','first_import_id','row_id','review_id','group_id','opening_id','approval_id','bank_transaction_id','bank_entry_id','movement_id','outgoing_id','incoming_id','receivable_payment_id','payment_id') and value is not null loop
  source_table:=case ref.key when 'import_id' then case when _table='bank_transactions' then null else 'finance_statement_imports' end when 'first_import_id' then 'finance_statement_imports' when 'row_id' then 'finance_statement_rows' when 'review_id' then 'finance_statement_identity_reviews' when 'group_id' then 'finance_reconciliation_groups' when 'opening_id' then 'finance_account_openings' when 'approval_id' then 'finance_statement_coverage_approvals' when 'bank_transaction_id' then 'bank_transactions' when 'bank_entry_id' then 'finance_bank_entries' when 'movement_id' then 'finance_movements' when 'outgoing_id' then 'finance_movements' when 'incoming_id' then 'finance_movements' when 'receivable_payment_id' then 'receivables_payments' when 'payment_id' then case when _table='receivable_payment_reversals' then 'receivables_payments' end end;
  if source_table is not null then
   if _table='receivable_payment_reversals' and ref.key='payment_id' and start_date is not null then continue;end if;
   execute format('select to_jsonb(s) from public.%I s where s.tenant_id=$1 and s.id=$2',source_table) into source using _tenant,ref.value::uuid;
   if source is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,source_table,source,_depth+1);hit:=true;
  end if;
 end loop;
 if _table='finance_reconciliation_groups' then
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'movement_ids') loop select to_jsonb(m) into source from public.finance_movements m where m.tenant_id=_tenant and m.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',source,_depth+1);end loop;
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'bank_entry_ids') loop select to_jsonb(e) into source from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_bank_entries',source,_depth+1);end loop;hit:=true;
 end if;
 if not hit then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
end$function$

CREATE OR REPLACE FUNCTION finance_private.record_expense_batch(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid; actor uuid:=auth.uid(); request uuid; trip uuid; driver uuid; batch uuid;
 existing public.finance_commands%rowtype; item jsonb; allocation jsonb; movement public.finance_movements%rowtype;
 cents bigint; allocated bigint; used bigint; linked bigint; expense uuid; payable uuid; unloading uuid;
 supplier uuid; cost_center uuid; supplier_name text; payee_name text; center_name text; actor_name text; result jsonb;
 rows jsonb:='[]'; discharge_result jsonb; context jsonb;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;trip:=nullif(_payload->>'trip_id','')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _payload->>'version' is distinct from '1'
 or coalesce(_payload->>'context','') not in('trip','office','personnel','maintenance','other')
 or ((_payload->>'context'='trip')<>(trip is not null))
 or jsonb_typeof(_payload->'items') is distinct from 'array' or jsonb_array_length(_payload->'items') not between 1 and 200
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or length(btrim(coalesce(_payload->>'description',''))) not between 1 and 1000
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','context','trip_id','description','reason','items')) then
  raise exception 'finance_invalid_batch' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'record_expense_batch' or existing.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505';end if;return existing.result;
 end if;
 if trip is not null then
  select driver_id into driver from public.dispatch_trips where id=trip and tenant_id=t and status='completed' for share;
  if not found then raise exception 'finance_trip_not_completed' using errcode='22023';end if;
 end if;
 insert into public.finance_expense_batches(tenant_id,context,trip_id,driver_id,description,created_by)
 values(t,_payload->>'context',trip,driver,btrim(_payload->>'description'),actor) returning id into batch;
 for item in select value from jsonb_array_elements(_payload->'items') loop
  expense:=(item->>'id')::uuid; supplier:=nullif(item->>'supplier_id','')::uuid;
  cost_center:=nullif(item->>'cost_center_id','')::uuid;payable:=null;unloading:=null;
  if expense is null or jsonb_typeof(item) is distinct from 'object'
  or coalesce(item->>'amount_cents','') !~ '^[0-9]{1,14}$'
  or coalesce(item->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$'
  or length(btrim(coalesce(item->>'description',''))) not between 1 and 1000
  or jsonb_typeof(item->'allocations') is distinct from 'array' or jsonb_array_length(item->'allocations')>100
  or exists(select 1 from jsonb_object_keys(item) k where k not in('id','category','description','amount_cents','occurred_on',
   'supplier_id','supplier_name','cost_center_id','document_number','receipt_path','no_receipt_reason','due_date','allocations','stop_id','delivery_revision','payee_type')) then
   raise exception 'finance_invalid_expense_item' using errcode='22023';end if;
  cents:=(item->>'amount_cents')::bigint;
  if cents<=0 or (item->>'occurred_on')::date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then
   raise exception 'finance_invalid_expense_amount_or_date' using errcode='22023';end if;
  if nullif(item->>'receipt_path','') is null then
   if length(btrim(coalesce(item->>'no_receipt_reason','')))<5 then raise exception 'finance_receipt_required' using errcode='22023';end if;
  elsif (item->>'receipt_path') not like t::text||'/%' or (item->>'receipt_path') like '%..%' then
   raise exception 'finance_invalid_receipt_scope' using errcode='22023';end if;
  supplier_name:=btrim(coalesce(item->>'supplier_name',''));
  if supplier is not null then
   select company_name into supplier_name from public.clients where id=supplier and tenant_id=t and active for share;
   if not found then raise exception 'finance_invalid_supplier' using errcode='22023';end if;
  end if;
  if supplier_name='' or supplier_name is null then raise exception 'finance_supplier_name_required' using errcode='22023';end if;
  center_name:=null;
  if cost_center is not null then
   select name into center_name from public.cost_centers where id=cost_center and tenant_id=t and active for share;
   if not found then raise exception 'finance_invalid_cost_center' using errcode='22023';end if;
  end if;
  allocated:=0;
  for allocation in select value from jsonb_array_elements(item->'allocations') loop
   if coalesce(allocation->>'amount_cents','') !~ '^[0-9]{1,14}$' then raise exception 'finance_invalid_allocation' using errcode='22023';end if;
   linked:=(allocation->>'amount_cents')::bigint;
   select * into movement from public.finance_movements where tenant_id=t and id=(allocation->>'movement_id')::uuid for share;
   if not found or movement.direction<>'out' or movement.nature='transfer'
    or (movement.driver_id is not null and movement.driver_id is distinct from driver) then
    raise exception 'finance_invalid_expense_movement' using errcode='22023';end if;
   select coalesce(sum(amount_cents),0) into used from public.finance_expense_allocations where tenant_id=t and movement_id=movement.id;
   if linked<=0 or used+linked>movement.amount_cents then raise exception 'finance_movement_overallocated' using errcode='23514';end if;
   allocated:=allocated+linked;
  end loop;
  if allocated>cents then raise exception 'finance_expense_overallocated' using errcode='23514';end if;
  if item->>'category'='unloading' then
   if trip is null or nullif(item->>'stop_id','') is null then raise exception 'finance_unloading_delivery_required' using errcode='22023';end if;
   context:=finance_private.delivery_context(t,(item->>'stop_id')::uuid);
   if context->>'trip_id' is distinct from trip::text then raise exception 'finance_unloading_trip_mismatch' using errcode='22023';end if;
   discharge_result:=finance_private.record_unloading(jsonb_build_object('version',1,'tenant_id',t,'request_id',expense,
    'stop_id',item->>'stop_id','expected_revision',item->>'delivery_revision','amount_cents',cents,'occurred_on',item->>'occurred_on',
    'due_date',item->>'due_date','receipt_path',item->>'receipt_path','reason',_payload->>'reason'));
   unloading:=(discharge_result->>'charge_id')::uuid;
  end if;
  if allocated<cents then
   if coalesce(item->>'payee_type','') not in('driver','supplier') then
    raise exception 'finance_payee_required' using errcode='22023';end if;
   payee_name:=supplier_name;
   if item->>'payee_type'='driver' then
    select name into payee_name from public.drivers where id=driver and tenant_id=t;
    if not found then raise exception 'finance_invalid_payee' using errcode='22023';end if;
   end if;
   insert into public.payables(tenant_id,supplier_name,supplier_id,category,description,amount,due_date,competence_date,
    status,driver_id,dispatch_trip_id,document_number,receipt_url,created_by,source_table,source_id,cost_center)
   values(t,payee_name,case when item->>'payee_type'='supplier' then supplier end,
    case when item->>'category' in('fuel','toll','maintenance','payroll','tax','rent','service') then item->>'category' else 'other' end,
    item->>'description',(cents-allocated)::numeric/100,
    nullif(item->>'due_date','')::date,(item->>'occurred_on')::date,'pending',driver,trip,
    nullif(item->>'document_number',''),nullif(item->>'receipt_path',''),actor,'finance_expense_items',expense,center_name)
   returning id into payable;
  end if;
  insert into public.finance_expense_items(id,tenant_id,batch_id,category,description,amount_cents,occurred_on,supplier_id,supplier_name,
   cost_center_id,document_number,receipt_path,no_receipt_reason,payable_id,unloading_id,created_by)
  values(expense,t,batch,item->>'category',btrim(item->>'description'),cents,(item->>'occurred_on')::date,supplier,supplier_name,
   cost_center,nullif(item->>'document_number',''),nullif(item->>'receipt_path',''),nullif(item->>'no_receipt_reason',''),payable,unloading,actor);
  for allocation in select value from jsonb_array_elements(item->'allocations') loop
   insert into public.finance_expense_allocations(tenant_id,expense_id,movement_id,amount_cents,created_by)
   values(t,expense,(allocation->>'movement_id')::uuid,(allocation->>'amount_cents')::bigint,actor);
  end loop;
  rows:=rows||jsonb_build_array(jsonb_build_object('expense_id',expense,'payable_id',payable,'unloading_id',unloading));
 end loop;
 select coalesce(raw_user_meta_data->>'full_name',email,actor::text) into actor_name from auth.users where id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(t,'expense_batch',batch,'recorded',actor,coalesce(actor_name,actor::text),_payload->>'reason',_payload);
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'batch_id',batch,'rows',rows,'confirmed',true);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result)
 values(t,request,actor,'record_expense_batch',_payload,result);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.record_movement(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 t uuid; actor uuid:=auth.uid(); request uuid; existing public.finance_commands%rowtype;
 movement uuid; account uuid; driver uuid; cents bigint; result jsonb; actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 t:=(_payload->>'tenant_id')::uuid; request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501'; end if;
 if request is null or _payload->>'version' is distinct from '1'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in
 ('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
  'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason')) then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 -- Serializes retries and reference checks, including requests with different IDs.
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'record_movement' or existing.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 cents:=(_payload->>'amount_cents')::bigint;
 if cents<=0 or (_payload->>'occurred_on')::date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then
  raise exception 'finance_invalid_realized_movement' using errcode='22023'; end if;
 account:=(_payload->>'bank_account_id')::uuid; driver:=nullif(_payload->>'driver_id','')::uuid;
 perform 1 from public.bank_accounts where id=account and tenant_id=t and active for share;
 if not found then raise exception 'finance_invalid_account' using errcode='22023'; end if;
 if driver is not null then
  perform 1 from public.drivers where id=driver and tenant_id=t and active for share;
  if not found then raise exception 'finance_invalid_driver' using errcode='22023'; end if;
 end if;
 if _payload->>'nature'='driver_advance' and (driver is null or _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_driver_advance' using errcode='22023'; end if;
 if (_payload->>'nature' in ('receipt','customer_advance') and _payload->>'direction' is distinct from 'in')
 or (_payload->>'nature'='payment' and _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_direction' using errcode='22023';end if;
 if nullif(btrim(_payload->>'receipt_path'),'') is not null and
  ((_payload->>'receipt_path') not like t::text||'/%' or (_payload->>'receipt_path') like '%..%') then
  raise exception 'finance_invalid_receipt_scope' using errcode='22023'; end if;
 if nullif(btrim(_payload->>'bank_reference'),'') is not null and exists(
  select 1 from public.finance_movements where tenant_id=t and bank_account_id=account
   and bank_reference=btrim(_payload->>'bank_reference')) then
  raise exception 'finance_reference_already_recorded' using errcode='23505'; end if;
 insert into public.finance_movements(tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,
  description,beneficiary_name,beneficiary_document,driver_id,bank_reference,receipt_path,created_by)
 values(t,account,_payload->>'direction',_payload->>'nature',cents,(_payload->>'occurred_on')::date,
  btrim(_payload->>'description'),btrim(_payload->>'beneficiary_name'),nullif(btrim(_payload->>'beneficiary_document'),''),
  driver,nullif(btrim(_payload->>'bank_reference'),''),nullif(btrim(_payload->>'receipt_path'),''),actor)
 returning id into movement;
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 select t,'movement',movement,'recorded',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),to_jsonb(m)
 from public.finance_movements m where m.id=movement;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'movement_id',movement,'confirmed',true);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result)
 values(t,request,actor,'record_movement',_payload,result);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.check_receipt_movement_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.finance_movements%rowtype;p public.receivables_payments%rowtype;issue text;cents numeric;begin
 if tg_table_name='finance_receivable_movement_links' then
  if new.action='reverse' then return new;end if;
 end if;
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0));
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into p from public.receivables_payments where tenant_id=new.tenant_id and id=new.payment_id;
 if not found or p.amount is null or p.amount::text in('NaN','Infinity','-Infinity') or p.amount<=0 or p.amount*100<>trunc(p.amount*100) or p.amount*100>99999999999999 then raise exception 'finance_legacy_receipt_amount_invalid' using errcode='23514';end if;
 cents:=p.amount*100;
 select * into m from public.finance_movements where tenant_id=new.tenant_id and id=new.movement_id;
 if not found or m.direction<>'in' or m.nature not in('receipt','customer_advance','other') or m.bank_account_id is distinct from p.bank_account_id or m.occurred_on is distinct from (p.received_at at time zone 'America/Sao_Paulo')::date then raise exception 'finance_receipt_movement_incompatible' using errcode='23514';end if;
 if tg_table_name='finance_legacy_receipt_movement_links' then
  issue:=finance_private.legacy_receivable_payment_issue(new.tenant_id,new.payment_id);
  if issue is not null then raise exception '%',issue using errcode='23514';end if;
  if new.amount_cents::numeric is distinct from cents or new.receivable_id is distinct from p.receivable_id then raise exception 'finance_legacy_receipt_link_mismatch' using errcode='23514';end if;
 else
  if exists(select 1 from public.finance_legacy_receipt_movement_links where tenant_id=new.tenant_id and payment_id=p.id)
   or exists(select 1 from public.finance_receivable_movement_links where tenant_id=new.tenant_id and payment_id=p.id and action='receive') then raise exception 'finance_receipt_already_linked' using errcode='23505';end if;
 end if;
 if finance_private.receipt_movement_used_cents(new.tenant_id,new.movement_id)+cents>m.amount_cents then raise exception 'finance_receipt_movement_capacity_exceeded' using errcode='23514';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.manage_legacy_receivable_association(_payload jsonb, _reverse boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;actor uuid:=auth.uid();actor_name text;p public.receivables_payments%rowtype;m public.finance_movements%rowtype;
 l public.finance_legacy_receipt_movement_links%rowtype;prior public.finance_commands%rowtype;link uuid;reversal uuid;issue text;action text;source jsonb;result jsonb;cents bigint;begin
 if jsonb_typeof(_payload) is distinct from 'object' then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if request is null or _reverse is null or _payload->'version' is distinct from '1'::jsonb or jsonb_typeof(_payload->'reason') is distinct from 'string'
  or length(btrim(coalesce(_payload->>'reason',''))) not between 10 and 2000
  or exists(select 1 from jsonb_object_keys(_payload) k where k<>all(case when _reverse then array['version','tenant_id','request_id','link_id','reason'] else array['version','tenant_id','request_id','payment_id','movement_id','revision','reason','existing_receipt_confirmed'] end)) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if not _reverse and (_payload->'existing_receipt_confirmed' is distinct from 'true'::jsonb or jsonb_typeof(_payload->'revision') is distinct from 'string' or coalesce(_payload->>'revision','') !~ '^[a-f0-9]{32}$') then raise exception 'finance_invalid_receipt_declaration' using errcode='22023';end if;
 action:=case when _reverse then 'reverse_legacy_receivable_association' else 'associate_legacy_receivable_payment' end;
 perform pg_advisory_xact_lock(hashtextextended('fiscal:'||t::text,0));perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if prior.actor_id<>actor or prior.action<>action or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;return prior.result;
 end if;
 if _reverse then
  select * into l from public.finance_legacy_receipt_movement_links where tenant_id=t and id=(_payload->>'link_id')::uuid;
  if not found then raise exception 'finance_legacy_receipt_association_not_found' using errcode='22023';end if;
  if exists(select 1 from public.finance_legacy_receipt_link_reversals where tenant_id=t and link_id=l.id) then raise exception 'finance_legacy_receipt_association_already_reversed' using errcode='22023';end if;
  select * into p from public.receivables_payments where tenant_id=t and id=l.payment_id;
 else select * into p from public.receivables_payments where tenant_id=t and id=(_payload->>'payment_id')::uuid;end if;
 if not found then raise exception 'finance_legacy_receipt_not_found' using errcode='22023';end if;
 perform public._lock_receivable_financial_graph(t,p.receivable_id);
 select * into p from public.receivables_payments where tenant_id=t and id=p.id for update;
 if not found then raise exception 'finance_legacy_receipt_not_found' using errcode='22023';end if;
 if p.bank_transaction_id is not null then perform 1 from public.bank_transactions where tenant_id=t and id=p.bank_transaction_id for share;end if;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;actor_name:=coalesce(actor_name,actor::text);
 if _reverse then
  insert into public.finance_legacy_receipt_link_reversals(tenant_id,link_id,created_by,actor_name,reason) values(t,l.id,actor,actor_name,btrim(_payload->>'reason')) returning id into reversal;
  result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'link_id',l.id,'payment_id',l.payment_id,'receivable_id',l.receivable_id,'movement_id',l.movement_id,'reversal_id',reversal,'released_cents',l.amount_cents::text,'origin','legacy_adoption','cash_changed',false,'payment_changed',false,'confirmed',true);
 else
  if finance_private.legacy_receivable_source_revision(t,p.id) is distinct from _payload->>'revision' then raise exception 'finance_legacy_receipt_changed' using errcode='40001';end if;
  issue:=finance_private.legacy_receivable_payment_issue(t,p.id);if issue is not null then raise exception '%',issue using errcode='23514';end if;
  cents:=(p.amount*100)::bigint;
  select * into m from public.finance_movements where tenant_id=t and id=(_payload->>'movement_id')::uuid;
  if not found or m.direction<>'in' or m.nature not in('receipt','customer_advance','other') or m.bank_account_id is distinct from p.bank_account_id
   or m.occurred_on is distinct from (p.received_at at time zone 'America/Sao_Paulo')::date then raise exception 'finance_receipt_movement_incompatible' using errcode='23514';end if;
  source:=jsonb_build_object('payment',to_jsonb(p),'receivable',(select to_jsonb(r) from public.receivables r where r.tenant_id=t and r.id=p.receivable_id),'bank_transaction',(select to_jsonb(b) from public.bank_transactions b where b.tenant_id=t and b.id=p.bank_transaction_id),'load_projections',coalesce((select jsonb_agg(to_jsonb(a) order by a.id) from public.load_payments a where a.tenant_id=t and (a.receivable_payment_id=p.id or a.bank_transaction_id=p.bank_transaction_id)),'[]'),'revision',_payload->>'revision','existing_receipt_confirmed',true);
  insert into public.finance_legacy_receipt_movement_links(tenant_id,payment_id,receivable_id,movement_id,amount_cents,created_by,actor_name,reason,source_snapshot)
  values(t,p.id,p.receivable_id,m.id,cents,actor,actor_name,btrim(_payload->>'reason'),source) returning id into link;
  result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'payment_id',p.id,'receivable_id',p.receivable_id,'movement_id',m.id,'link_id',link,'amount_cents',cents::text,'bank_transaction_id',p.bank_transaction_id,'origin','legacy_adoption','cash_created',false,'payment_created',false,'confirmed',true);
 end if;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data)
 values(t,'receivable_payment',p.id,case when _reverse then 'legacy_receivable_association_reversed' else 'legacy_receivable_associated' end,actor,actor_name,btrim(_payload->>'reason'),case when _reverse then to_jsonb(l) else source end,result||jsonb_build_object('manual_intervention',true));
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,action,_payload,result);return result;
end$function$

CREATE OR REPLACE FUNCTION finance_private.project_receivable_command()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment public.receivables_payments%rowtype;tx public.bank_transactions%rowtype;reversal public.receivable_payment_reversals%rowtype;
 movement uuid;party text;actor_name text;effective_at timestamptz;amount numeric;receipt text;description text;
 selected public.finance_movements%rowtype;allocated numeric;
begin
 if new.action not in('receive','reverse') then return new;end if;
 if new.actor_id is distinct from auth.uid() or not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into payment from public.receivables_payments where tenant_id=new.tenant_id and receivable_id=new.receivable_id and id=(new.response->>'payment_id')::uuid;
 if not found then raise exception 'finance_receipt_projection_source_missing' using errcode='23514';end if;
 select * into tx from public.bank_transactions where tenant_id=new.tenant_id and id=(new.response->>'bank_transaction_id')::uuid;
 if not found or tx.bank_account_id is distinct from payment.bank_account_id then raise exception 'finance_receipt_projection_bank_mismatch' using errcode='23514';end if;
 if new.action='receive' then
  if payment.financial_command_id is distinct from new.id or payment.bank_transaction_id is distinct from tx.id or tx.transaction_type<>'credit' then raise exception 'finance_receipt_projection_source_mismatch' using errcode='23514';end if;
  effective_at:=payment.received_at;amount:=payment.amount;receipt:=payment.attachment_url;
 else
  select * into reversal from public.receivable_payment_reversals where tenant_id=new.tenant_id and financial_command_id=new.id and payment_id=payment.id and bank_transaction_id=tx.id;
  if not found or tx.transaction_type<>'debit' then raise exception 'finance_receipt_projection_reversal_mismatch' using errcode='23514';end if;
  effective_at:=reversal.effective_at;amount:=reversal.amount;
 end if;
 if amount is null or amount<=0 or amount*100<>trunc(amount*100) or amount*100>99999999999999 or amount is distinct from tx.amount
  or effective_at is distinct from tx.posted_at then raise exception 'finance_receipt_projection_amount_mismatch' using errcode='23514';end if;
 select coalesce(nullif(btrim(to_jsonb(c)->>'company_name'),''),nullif(btrim(to_jsonb(c)->>'name'),'')) into party
  from public.receivables r join public.clients c on c.tenant_id=r.tenant_id and c.id=r.client_id where r.tenant_id=new.tenant_id and r.id=new.receivable_id;
 party:=coalesce(party,'Contraparte não identificada');
 description:=case when new.action='receive' then 'Recebimento registrado: ' else 'Devolução registrada de recebimento: ' end||coalesce(new.before_snapshot->>'reference',new.receivable_id::text);
 if new.action='receive' and new.response ? 'movement_id' then
  select * into selected from public.finance_movements where tenant_id=new.tenant_id and id=(new.response->>'movement_id')::uuid;
  if not found or selected.direction<>'in' or selected.nature not in('receipt','customer_advance','other')
   or selected.bank_account_id<>tx.bank_account_id or selected.occurred_on<>(effective_at at time zone 'America/Sao_Paulo')::date then
   raise exception 'finance_receipt_movement_incompatible' using errcode='23514';end if;
  allocated:=finance_private.receipt_movement_used_cents(new.tenant_id,selected.id); if allocated+amount*100>selected.amount_cents then raise exception 'finance_receipt_movement_capacity_exceeded' using errcode='23514';end if;
  movement:=selected.id;
 else
 insert into public.finance_movements(tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,description,beneficiary_name,receipt_path,created_by)
 values(new.tenant_id,tx.bank_account_id,case when new.action='receive' then 'in' else 'out' end,case when new.action='receive' then 'receipt' else 'refund' end,
  (amount*100)::bigint,(effective_at at time zone 'America/Sao_Paulo')::date,left(description,1000),left(party,300),receipt,new.actor_id) returning id into movement;
 end if;
 insert into public.finance_receivable_movement_links(tenant_id,command_id,payment_id,bank_transaction_id,movement_id,action)
 values(new.tenant_id,new.id,payment.id,tx.id,movement,new.action);
 select coalesce(raw_user_meta_data->>'full_name',email,new.actor_id::text) into actor_name from auth.users where id=new.actor_id;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 values(new.tenant_id,'movement',movement,'receivable_movement_recorded',new.actor_id,coalesce(actor_name,new.actor_id::text),new.reason,
  jsonb_build_object('movement_id',movement,'receivable_id',new.receivable_id,'payment_id',payment.id,'command_id',new.id,'legacy_bank_transaction_id',tx.id,'source_action',new.action,'refund_kind',new.response->>'refund_kind','bank_confirmed',false));
 return new;
end;$function$

CREATE OR REPLACE FUNCTION finance_private.receipt_movement_options(_tenant uuid, _account uuid, _date date, _search text, _page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare result jsonb;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _date is null or _page is null or _page not between 1 and 1000000 or _search is null or length(_search)>200 then raise exception 'finance_invalid_filters' using errcode='22023';end if;
 if not exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=_account) then raise exception 'finance_account_not_found' using errcode='22023';end if;
 with candidates as materialized(
  select m.*,m.amount_cents-finance_private.receipt_movement_used_cents(_tenant,m.id) available
  from public.finance_movements m where m.tenant_id=_tenant and m.bank_account_id=_account and m.occurred_on=_date and m.direction='in' and m.nature in('receipt','customer_advance','other')
   and (_search='' or strpos(lower(m.description||' '||m.beneficiary_name||' '||coalesce(m.bank_reference,'')),lower(_search))>0)
 ), available as materialized(select * from candidates where available>0),paged as(select * from available order by created_at desc,id desc limit 20 offset (_page-1)*20)
 select jsonb_build_object('version',1,'tenant_id',_tenant,'bank_account_id',_account,'date',_date,'page',_page,'page_size',20,'total',(select count(*) from available),
  'rows',coalesce((select jsonb_agg(jsonb_build_object('id',id,'description',description,'counterparty',beneficiary_name,'amount_cents',amount_cents::text,'available_cents',available::text,'bank_reference',bank_reference) order by created_at desc,id desc) from paged),'[]')) into result;
 return result;
end;$function$

CREATE OR REPLACE FUNCTION finance_private.record_movement(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 t uuid; actor uuid:=auth.uid(); request uuid; existing public.finance_commands%rowtype;
 movement uuid; account uuid; driver uuid; cents bigint; result jsonb; actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 t:=(_payload->>'tenant_id')::uuid; request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501'; end if;
 if request is null or _payload->>'version' is distinct from '1'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in
 ('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
  'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason')) then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 -- Serializes retries and reference checks, including requests with different IDs.
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'record_movement' or existing.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 cents:=(_payload->>'amount_cents')::bigint;
 if cents<=0 or (_payload->>'occurred_on')::date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then
  raise exception 'finance_invalid_realized_movement' using errcode='22023'; end if;
 account:=(_payload->>'bank_account_id')::uuid; driver:=nullif(_payload->>'driver_id','')::uuid;
 perform 1 from public.bank_accounts where id=account and tenant_id=t and active for share;
 if not found then raise exception 'finance_invalid_account' using errcode='22023'; end if;
 if driver is not null then
  perform 1 from public.drivers where id=driver and tenant_id=t and active for share;
  if not found then raise exception 'finance_invalid_driver' using errcode='22023'; end if;
 end if;
 if _payload->>'nature'='driver_advance' and (driver is null or _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_driver_advance' using errcode='22023'; end if;
 if (_payload->>'nature' in ('receipt','customer_advance') and _payload->>'direction' is distinct from 'in')
 or (_payload->>'nature'='payment' and _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_direction' using errcode='22023';end if;
 if nullif(btrim(_payload->>'receipt_path'),'') is not null and
  ((_payload->>'receipt_path') not like t::text||'/%' or (_payload->>'receipt_path') like '%..%') then
  raise exception 'finance_invalid_receipt_scope' using errcode='22023'; end if;
 if nullif(btrim(_payload->>'bank_reference'),'') is not null and exists(
  select 1 from public.finance_movements where tenant_id=t and bank_account_id=account
   and bank_reference=btrim(_payload->>'bank_reference')) then
  raise exception 'finance_reference_already_recorded' using errcode='23505'; end if;
 insert into public.finance_movements(tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,
  description,beneficiary_name,beneficiary_document,driver_id,bank_reference,receipt_path,created_by)
 values(t,account,_payload->>'direction',_payload->>'nature',cents,(_payload->>'occurred_on')::date,
  btrim(_payload->>'description'),btrim(_payload->>'beneficiary_name'),nullif(btrim(_payload->>'beneficiary_document'),''),
  driver,nullif(btrim(_payload->>'bank_reference'),''),nullif(btrim(_payload->>'receipt_path'),''),actor)
 returning id into movement;
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 select t,'movement',movement,'recorded',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),to_jsonb(m)
 from public.finance_movements m where m.id=movement;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'movement_id',movement,'confirmed',true);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result)
 values(t,request,actor,'record_movement',_payload,result);
 return result;
end;
$function$
